### Overlay test: `/data/vela/apps/examples/fboverlay/fboverlay_main.c`

A command-line tool for testing overlay features. Shows how to:

```c
// Get video info
ioctl(fb, FBIOGET_VIDEOINFO, (unsigned long)(uintptr_t)&vinfo);

// Get plane info + mmap
ioctl(fb, FBIOGET_PLANEINFO, (unsigned long)(uintptr_t)&pinfo);
fbmem = mmap(NULL, pinfo.fblen, PROT_READ | PROT_WRITE,
             MAP_SHARED | MAP_FILE, fb, 0);

// Select an overlay
ioctl(fb, FBIO_SELECT_OVERLAY, overlayno);

// Get overlay info + mmap
oinfo.overlay = overlayno;
ioctl(fb, FBIOGET_OVERLAYINFO, (unsigned long)(uintptr_t)&oinfo);
fbmem = mmap(NULL, oinfo.fblen, PROT_READ | PROT_WRITE,
             MAP_SHARED | MAP_FILE, fb, 0);

// Colormap operations
ioctl(fb, FBIOPUT_CMAP, (unsigned long)(uintptr_t)cmap);
ioctl(fb, FBIOGET_CMAP, (unsigned long)(uintptr_t)cmap);

// Overlay controls
ioctl(fb, FBIOSET_BLANK, (unsigned long)(uintptr_t)&oinfo);
ioctl(fb, FBIOSET_COLOR, (unsigned long)(uintptr_t)&oinfo);
ioctl(fb, FBIOSET_CHROMAKEY, (unsigned long)(uintptr_t)&oinfo);
ioctl(fb, FBIOSET_TRANSP, (unsigned long)(uintptr_t)&oinfo);
ioctl(fb, FBIOSET_AREA, (unsigned long)(uintptr_t)&oinfo);
ioctl(fb, FBIO_WAITFORVSYNC, 0);
```

