## 10. Quickstart Pattern

To get display info and write raw pixels, the canonical pattern is:

```c
#include <nuttx/video/fb.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <fcntl.h>

struct fb_videoinfo_s vinfo;
struct fb_planeinfo_s pinfo;
void *fbmem;

int fd = open("/dev/fb0", O_RDWR);
ioctl(fd, FBIOGET_VIDEOINFO, (unsigned long)&vinfo);
ioctl(fd, FBIOGET_PLANEINFO, (unsigned long)&pinfo);
fbmem = mmap(NULL, pinfo.fblen, PROT_READ|PROT_WRITE, MAP_SHARED|MAP_FILE, fd, 0);

// Write a red pixel at (x, y) for 32bpp:
uint32_t *pixel = (uint32_t*)((uint8_t*)fbmem + y * pinfo.stride + x * 4);
*pixel = 0xFFFF0000;  // ARGB: red

// For 16bpp (RGB565):
uint16_t *pixel16 = (uint16_t*)((uint8_t*)fbmem + y * pinfo.stride + x * 2);
*pixel16 = 0xF800;  // red in RGB565

munmap(fbmem, pinfo.fblen);
close(fd);
```

