### 3. Architecture and Function Breakdown

The file is structured as a single C source with static helper functions and a `main()` that dispatches on `argv[1]`.

```
main(argc, argv)
  |
  +-- argv[1] == NULL or "all" or invalid
  |     -> run_mode_info()
  |     -> run_mode_raw()
  |     -> run_mode_lvgl()
  |
  +-- argv[1] == "info"
  |     -> run_mode_info()
  |
  +-- argv[1] == "raw"
  |     -> run_mode_raw()
  |
  +-- argv[1] == "lvgl"
        -> run_mode_lvgl()
```

#### Function Signatures and Responsibilities

```c
/* --- Mode 1: System/Display Info --- */
static int run_mode_info(void);
// Returns 0 on success, 1 on failure.
// Opens /proc/meminfo, reads line-by-line, parses tabular columns.
// Opens /dev/fb0, calls FBIOGET_VIDEOINFO, FBIOGET_PLANEINFO, FBIOGET_FRAMERATE.
// Prints all results to stdout with [INFO] prefix.

/* --- Mode 2: Raw Framebuffer Test --- */
static int run_mode_raw(void);
// Returns 0 on success, 1 on failure.
// Opens /dev/fb0, ioctl to get vinfo/pinfo, mmap framebuffer.
// Runs phases A-E with 2-second waits between each.
// Munmaps and closes before returning.

/* --- Helper: fill entire framebuffer with a solid 32bpp color --- */
static void raw_fill_screen(FAR uint32_t *fbmem, fb_coord_t stride, fb_coord_t xres, fb_coord_t yres, uint32_t color);
// Writes 'color' to every pixel. stride is in bytes; divide by 4 for uint32_t stride.

/* --- Helper: draw vertical color bars (32bpp) --- */
static void raw_draw_bars(FAR uint32_t *fbmem, fb_coord_t stride, fb_coord_t xres, fb_coord_t yres);

/* --- Helper: draw 1-pixel border (32bpp) --- */
static void raw_draw_border(FAR uint32_t *fbmem, fb_coord_t stride, fb_coord_t xres, fb_coord_t yres, uint32_t color);

/* --- Mode 3: LVGL Test --- */
static int run_mode_lvgl(void);
// Returns 0 on success, 1 on failure.
// Calls lv_init(), lv_mem_monitor() for baseline, lv_nuttx_init(),
// draws test pattern, then loops calling lv_timer_handler() with periodic mem monitoring.

/* --- Existing color grid test (kept as-is or slightly adapted) --- */
static void draw_test_pattern(void);
// Uses lv_scr_act() and lv_obj_create/lv_label_create to draw a 3x4 color grid.
// Remains essentially unchanged except maybe resolution labels.
```

### 4. Detailed Implementation for Each Function

#### 4.1 `run_mode_info()`

**Step-by-step:**

1. **Print section header:**
```c
printf("===== System/Display Information =====\n");
```

2. **Read /proc/meminfo:**
```c
FILE *fp = fopen("/proc/meminfo", "r");
if (fp == NULL) {
    printf("[INFO] /proc/meminfo not available (CONFIG_FS_PROCFS)\n");
} else {
    char line[256];
    // Skip header line
    if (fgets(line, sizeof(line), fp)) {
        // Parse data lines: "%lu%lu%lu%lu%lu%lu%lu %s"
        while (fgets(line, sizeof(line), fp)) {
            unsigned long total, used, free, maxused, maxfree;
            unsigned long nused, nfree;
            char name[32];
            int n = sscanf(line, "%lu%lu%lu%lu%lu%lu%lu %31s",
                           &total, &used, &free, &maxused,
                           &maxfree, &nused, &nfree, name);
            if (n >= 8) {
                printf("[INFO] Heap '%s': total=%lu KB used=%lu KB free=%lu KB\n",
                       name, total / 1024, used / 1024, free / 1024);
            }
        }
    }
    fclose(fp);
}
```

**Note on /proc/meminfo format:** NuttX's `/proc/meminfo` outputs columns strongly-typed as:
```
      total      used       free   maxused   maxfree   nused   nfree name
   8388608   1048576   7340032   1048576   7340032      16      32  Heap
```
We extract `total` (arena = MemTotal equivalent), `free` (fordblks = MemFree equivalent), `used` (uordblks). There is no direct MemAvailable equivalent in NuttX. We label clearly.

3. **Open /dev/fb0:**
```c
int fd = open("/dev/fb0", O_RDWR);
if (fd < 0) {
    printf("[FAIL] Failed to open /dev/fb0: %d\n", errno);
    return 1;
}
```

4. **FBIOGET_VIDEOINFO:**
```c
struct fb_videoinfo_s vinfo;
int ret = ioctl(fd, FBIOGET_VIDEOINFO, (unsigned long)(uintptr_t)&vinfo);
if (ret < 0) {
    printf("[FAIL] ioctl(FBIOGET_VIDEOINFO) failed: %d\n", errno);
    close(fd);
    return 1;
}
printf("[INFO] VideoInfo: fmt=%u xres=%u yres=%u nplanes=%u\n",
       vinfo.fmt, vinfo.xres, vinfo.yres, vinfo.nplanes);
// Translate fmt to string
const char *fmt_str = "UNKNOWN";
switch (vinfo.fmt) {
    case FB_FMT_RGB32:   fmt_str = "RGB32";   break;
    case FB_FMT_RGB24:   fmt_str = "RGB24";   break;
    case FB_FMT_RGB16_565: fmt_str = "RGB565"; break;
    case FB_FMT_RGB16_555: fmt_str = "RGB555"; break;
    // ... etc
}
printf("[INFO] format=%s xres=%u yres=%u nplanes=%u\n",
       fmt_str, vinfo.xres, vinfo.yres, vinfo.nplanes);
```

5. **FBIOGET_PLANEINFO:**
```c
struct fb_planeinfo_s pinfo;
memset(&pinfo, 0, sizeof(pinfo));
ret = ioctl(fd, FBIOGET_PLANEINFO, (unsigned long)(uintptr_t)&pinfo);
if (ret < 0) {
    printf("[FAIL] ioctl(FBIOGET_PLANEINFO) failed: %d\n", errno);
    close(fd);
    return 1;
}
printf("[INFO] PlaneInfo: fbmem=%p fblen=%zu stride=%u display=%u bpp=%u\n",
       pinfo.fbmem, pinfo.fblen, pinfo.stride, pinfo.display, pinfo.bpp);
```

6. **FBIOGET_FRAMERATE:**
```c
int framerate = 0;
ret = ioctl(fd, FBIOGET_FRAMERATE, (unsigned long)(uintptr_t)&framerate);
if (ret < 0) {
    printf("[INFO] FBIOGET_FRAMERATE not supported\n");
} else {
    printf("[INFO] framerate=%d fps\n", framerate);
}
```

7. **Print summary line** as requested:
```c
printf("[INFO] xres=%u yres=%u fmt=%s bpp=%u stride=%u\n",
       vinfo.xres, vinfo.yres, fmt_str, pinfo.bpp, pinfo.stride);
```

8. **Close fd and return:**
```c
close(fd);
return 0;
```

#### 4.2 `run_mode_raw()`

**Step-by-step:**

1. **Open /dev/fb0** with `O_RDWR`, get `vinfo` and `pinfo` via ioctl (same pattern as info mode).

2. **Check bpp** -- assert it is 32 (our test assumes 32bpp XRGB8888). If not 32, print `[FAIL] raw mode requires 32bpp, got bpp=%u` and return 1.

3. **mmap framebuffer:**
```c
FAR uint32_t *fbmem = (FAR uint32_t *)mmap(NULL, pinfo.fblen,
                                           PROT_READ | PROT_WRITE,
                                           MAP_SHARED | MAP_FILE, fd, 0);
if (fbmem == MAP_FAILED) {
    printf("[FAIL] mmap failed: %d\n", errno);
    close(fd);
    return 1;
}
```

4. **Phase A -- Solid RED:**
```c
printf("[RAW] Phase A: Fill RED - starting\n");
raw_fill_screen(fbmem, pinfo.stride, vinfo.xres, vinfo.yres, 0x00FF0000); // XRGB: B=0, G=0, R=255
printf("[RAW] Phase A: Fill RED - done\n");
usleep(2000 * 1000);
```

The `raw_fill_screen` implementation:
```c
static void raw_fill_screen(FAR uint32_t *fbmem, fb_coord_t stride,
                            fb_coord_t xres, fb_coord_t yres, uint32_t color)
{
    uint32_t stride_pixels = stride / 4;  /* stride is in bytes, 32bpp = 4 bytes/pixel */
    for (fb_coord_t y = 0; y < yres; y++) {
        FAR uint32_t *row = fbmem + y * stride_pixels;
        for (fb_coord_t x = 0; x < xres; x++) {
            row[x] = color;
        }
    }
}
```

5. **Phase B -- Solid GREEN:**
```c
printf("[RAW] Phase B: Fill GREEN - starting\n");
raw_fill_screen(fbmem, pinfo.stride, vinfo.xres, vinfo.yres, 0x0000FF00);
printf("[RAW] Phase B: Fill GREEN - done\n");
usleep(2000 * 1000);
```

6. **Phase C -- Solid BLUE:**
```c
printf("[RAW] Phase C: Fill BLUE - starting\n");
raw_fill_screen(fbmem, pinfo.stride, vinfo.xres, vinfo.yres, 0x000000FF);
printf("[RAW] Phase C: Fill BLUE - done\n");
usleep(2000 * 1000);
```

7. **Phase D -- Color bars (vertical stripes):**
```c
printf("[RAW] Phase D: Color bars - starting\n");
raw_draw_bars(fbmem, pinfo.stride, vinfo.xres, vinfo.yres);
printf("[RAW] Phase D: Color bars - done\n");
usleep(2000 * 1000);
```

The `raw_draw_bars` implementation:
```c
static void raw_draw_bars(FAR uint32_t *fbmem, fb_coord_t stride,
                          fb_coord_t xres, fb_coord_t yres)
{
    static const uint32_t bar_colors[] = {
        0x00FF0000,  /* RED    */
        0x0000FF00,  /* GREEN  */
        0x000000FF,  /* BLUE   */
        0x00FFFFFF,  /* WHITE  */
        0x00000000,  /* BLACK  */
        0x00FFFF00,  /* YELLOW (R+G) */
        0x0000FFFF,  /* CYAN   (G+B) */
        0x00FF00FF,  /* MAGENTA (R+B) */
    };
    int nbars = sizeof(bar_colors) / sizeof(bar_colors[0]);
    fb_coord_t bar_w = xres / nbars;
    uint32_t stride_pixels = stride / 4;

    for (int i = 0; i < nbars; i++) {
        fb_coord_t x_start = i * bar_w;
        fb_coord_t x_end = (i == nbars - 1) ? xres : (i + 1) * bar_w;
        for (fb_coord_t y = 0; y < yres; y++) {
            FAR uint32_t *row = fbmem + y * stride_pixels;
            for (fb_coord_t x = x_start; x < x_end; x++) {
                row[x] = bar_colors[i];
            }
        }
    }
}
```

8. **Phase E -- Border test:**
```c
printf("[RAW] Phase E: Border test - starting\n");
raw_draw_border(fbmem, pinfo.stride, vinfo.xres, vinfo.yres, 0x00FFFFFF); // white border
printf("[RAW] Phase E: Border test - done\n");
usleep(2000 * 1000);
```

The `raw_draw_border` implementation:
```c
static void raw_draw_border(FAR uint32_t *fbmem, fb_coord_t stride,
                            fb_coord_t xres, fb_coord_t yres, uint32_t color)
{
    uint32_t stride_pixels = stride / 4;

    // First clear screen to black
    raw_fill_screen(fbmem, stride, xres, yres, 0x00000000);

    // Top edge (y=0)
    for (fb_coord_t x = 0; x < xres; x++) {
        fbmem[x] = color;
    }
    // Bottom edge (y = yres-1)
    FAR uint32_t *last_row = fbmem + (yres - 1) * stride_pixels;
    for (fb_coord_t x = 0; x < xres; x++) {
        last_row[x] = color;
    }
    // Left edge (x=0)
    for (fb_coord_t y = 0; y < yres; y++) {
        FAR uint32_t *row = fbmem + y * stride_pixels;
        row[0] = color;
    }
    // Right edge (x = xres-1)
    for (fb_coord_t y = 0; y < yres; y++) {
        FAR uint32_t *row = fbmem + y * stride_pixels;
        row[xres - 1] = color;
    }
}
```

9. **Cleanup:**
```c
munmap(fbmem, pinfo.fblen);
close(fd);
printf("[PASS] Raw framebuffer test completed\n");
return 0;
```

#### 4.3 `run_mode_lvgl()`

**Step-by-step:**

1. **Initialize LVGL and print baseline memory:**
```c
printf("[LVGL] Initializing...\n");
lv_init();

lv_mem_monitor_t mem_before;
lv_mem_monitor(&mem_before);
printf("[MEM] Before LVGL init: total=%zu KB used=%zu KB free=%zu KB used_pct=%u%% frag_pct=%u%%\n",
       mem_before.total_size / 1024,
       (mem_before.total_size - mem_before.free_size) / 1024,
       mem_before.free_size / 1024,
       mem_before.used_pct,
       mem_before.frag_pct);
```

2. **Initialize NuttX display driver:**
```c
lv_nuttx_dsc_t info;
lv_nuttx_result_t result;
lv_nuttx_dsc_init(&info);
#ifdef CONFIG_LV_USE_NUTTX_LCD
info.fb_path = "/dev/lcd0";
#endif
#ifdef CONFIG_INPUT_TOUCHSCREEN
info.input_path = "/dev/input0";
#endif

lv_nuttx_init(&info, &result);

if (result.disp == NULL) {
    printf("[FAIL] lv_nuttx_init() returned NULL display\n");
    return 1;
}
```

3. **Print resolution and memory after init:**
```c
int32_t hor = lv_display_get_horizontal_resolution(NULL);
int32_t ver = lv_display_get_vertical_resolution(NULL);
// Or use compat macros: lv_disp_get_hor_res(result.disp)
printf("[LVGL] Display initialized: %dx%d\n", hor, ver);

lv_mem_monitor_t mem_after;
lv_mem_monitor(&mem_after);
printf("[MEM] After LVGL init: total=%zu KB used=%zu KB free=%zu KB used_pct=%u%% frag_pct=%u%%\n",
       mem_after.total_size / 1024,
       (mem_after.total_size - mem_after.free_size) / 1024,
       mem_after.free_size / 1024,
       mem_after.used_pct,
       mem_after.frag_pct);
```

4. **Draw test pattern (existing function):**
```c
draw_test_pattern();
```

5. **Main loop with periodic memory monitoring:**
```c
uint32_t iterations = 0;
while (1) {
    uint32_t idle = lv_timer_handler();
    idle = idle ? idle : 1;
    usleep(idle * 1000);

    iterations++;
    if (iterations % 300 == 0) {
        lv_mem_monitor_t mem;
        lv_mem_monitor(&mem);
        printf("[LVGL] mem used_pct=%u%% frag_pct=%u%% free=%zu KB (iter=%u)\n",
               mem.used_pct, mem.frag_pct,
               mem.free_size / 1024,
               iterations);
    }
}
```

Note: The loop runs indefinitely (same as current behavior). To exit cleanly, the user can press Ctrl-C. In a dedicated NuttX context, we could add a `read(STDIN_FILENO)` non-blocking check, but the current code doesn't have one and the enhanced version keeps this same pattern for backward compatibility.

Add before the loop (non-blocking stdin check for exit):
```c
#include <sys/select.h>  // or poll.h

// Add non-blocking check for 'q' key to exit cleanly
// (only if input is available)
struct timeval tv = { 0, 0 };
fd_set fds;
FD_ZERO(&fds);
FD_SET(STDIN_FILENO, &fds);
if (select(1, &fds, NULL, NULL, &tv) > 0) {
    char c;
    if (read(STDIN_FILENO, &c, 1) > 0 && c == 'q') {
        printf("[LVGL] User requested exit\n");
        break;
    }
}
```

This is an enhancement over the current infinite loop that cannot be exited.

6. **Cleanup (after break):**
```c
lv_nuttx_deinit(&result);
lv_deinit();
printf("[PASS] LVGL test completed\n");
return 0;
```

#### 4.4 `main()` -- Argument Dispatch

```c
int main(int argc, FAR char *argv[])
{
    if (argc >= 2) {
        if (strcmp(argv[1], "info") == 0) {
            return run_mode_info();
        } else if (strcmp(argv[1], "raw") == 0) {
            return run_mode_raw();
        } else if (strcmp(argv[1], "lvgl") == 0) {
            return run_mode_lvgl();
        } else if (strcmp(argv[1], "all") == 0) {
            goto run_all;
        } else {
            printf("Usage: screentest [info|raw|lvgl|all]\n");
            printf("  (no args) = run all tests sequentially\n");
            return 1;
        }
    } else {
run_all:
        printf("===== Running ALL tests sequentially =====\n");
        if (run_mode_info() != 0) {
            printf("[FAIL] Info test failed\n");
        }
        printf("\n");
        if (run_mode_raw() != 0) {
            printf("[FAIL] Raw framebuffer test failed\n");
        }
        printf("\n");
        if (run_mode_lvgl() != 0) {
            printf("[FAIL] LVGL test failed\n");
        }
        printf("===== All tests complete =====\n");
    }

    return 0;
}
```

