/****************************************************************************
 * apps/examples/screentest/screentest.c
 *
 * Enhanced screen test for 6FHD display (1080x2160) on R528
 *
 * Modes:
 *   screentest info  - Dump system/display info
 *   screentest raw   - Raw framebuffer test (bypass LVGL)
 *   screentest lvgl  - LVGL color grid + memory monitor
 *   screentest       - Run all tests sequentially
 *
 * Debug log prefixes: [INFO] [RAW] [LVGL] [MEM] [PASS] [FAIL]
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/video/fb.h>

#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>

#include <lvgl/lvgl.h>

/****************************************************************************
 * Preprocessor Definitions
 ****************************************************************************/

#define SCREEN_WIDTH  1080
#define SCREEN_HEIGHT 2160

/* Raw 32bpp colors (XRGB8888: 0xFFRRGGBB) */
#define RAW_RED     0xFFFF0000
#define RAW_GREEN   0xFF00FF00
#define RAW_BLUE    0xFF0000FF
#define RAW_WHITE   0xFFFFFFFF
#define RAW_BLACK   0xFF000000
#define RAW_YELLOW  0xFFFFFF00
#define RAW_CYAN    0xFF00FFFF
#define RAW_MAGENTA 0xFFFF00FF

#define FB_DEVICE   "/dev/fb0"

/* Grid: 3 columns x 4 rows for LVGL test */
#define GRID_COLS 3
#define GRID_ROWS 4
#define CELL_W (SCREEN_WIDTH / GRID_COLS)
#define CELL_H (SCREEN_HEIGHT / GRID_ROWS)

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const uint32_t raw_bar_colors[] = {
    RAW_RED, RAW_GREEN, RAW_BLUE,
    RAW_WHITE, RAW_BLACK,
    RAW_YELLOW, RAW_CYAN, RAW_MAGENTA,
};

static const lv_color_t grid_colors[GRID_ROWS][GRID_COLS] = {
    {LV_COLOR_MAKE(0xFF, 0x00, 0x00), LV_COLOR_MAKE(0x00, 0xFF, 0x00), LV_COLOR_MAKE(0x00, 0x00, 0xFF)},
    {LV_COLOR_MAKE(0xFF, 0xFF, 0x00), LV_COLOR_MAKE(0x00, 0xFF, 0xFF), LV_COLOR_MAKE(0xFF, 0x00, 0xFF)},
    {LV_COLOR_MAKE(0xFF, 0xFF, 0xFF), LV_COLOR_MAKE(0x80, 0x80, 0x80), LV_COLOR_MAKE(0x00, 0x00, 0x00)},
    {LV_COLOR_MAKE(0xFF, 0x80, 0x00), LV_COLOR_MAKE(0x80, 0x00, 0xFF), LV_COLOR_MAKE(0x00, 0x80, 0x80)},
};

/****************************************************************************
 * Private Functions - Raw Framebuffer Helpers
 ****************************************************************************/

static void raw_fill_screen(FAR uint32_t *fbmem, fb_coord_t stride,
                            fb_coord_t xres, fb_coord_t yres, uint32_t color)
{
    uint32_t stride_pixels = stride / 4;
    for (fb_coord_t y = 0; y < yres; y++)
    {
        FAR uint32_t *row = fbmem + y * stride_pixels;
        for (fb_coord_t x = 0; x < xres; x++)
        {
            row[x] = color;
        }
    }
}

static void raw_draw_bars(FAR uint32_t *fbmem, fb_coord_t stride,
                          fb_coord_t xres, fb_coord_t yres)
{
    int nbars = sizeof(raw_bar_colors) / sizeof(raw_bar_colors[0]);
    fb_coord_t bar_w = xres / nbars;
    uint32_t stride_pixels = stride / 4;

    for (int i = 0; i < nbars; i++)
    {
        fb_coord_t x_start = i * bar_w;
        fb_coord_t x_end = (i == nbars - 1) ? xres : (i + 1) * bar_w;
        for (fb_coord_t y = 0; y < yres; y++)
        {
            FAR uint32_t *row = fbmem + y * stride_pixels;
            for (fb_coord_t x = x_start; x < x_end; x++)
            {
                row[x] = raw_bar_colors[i];
            }
        }
    }
}

static void raw_draw_border(FAR uint32_t *fbmem, fb_coord_t stride,
                            fb_coord_t xres, fb_coord_t yres, uint32_t color)
{
    uint32_t stride_pixels = stride / 4;

    /* Clear to black first */
    raw_fill_screen(fbmem, stride, xres, yres, RAW_BLACK);

    /* Top edge */
    for (fb_coord_t x = 0; x < xres; x++)
    {
        fbmem[x] = color;
    }

    /* Bottom edge */
    FAR uint32_t *last_row = fbmem + (yres - 1) * stride_pixels;
    for (fb_coord_t x = 0; x < xres; x++)
    {
        last_row[x] = color;
    }

    /* Left and right edges */
    for (fb_coord_t y = 1; y < yres - 1; y++)
    {
        FAR uint32_t *row = fbmem + y * stride_pixels;
        row[0] = color;
        row[xres - 1] = color;
    }
}

/****************************************************************************
 * Private Functions - Test Modes
 ****************************************************************************/

static int run_mode_info(void)
{
    printf("===== [INFO] System/Display Information =====\n");

    /* Read /proc/meminfo */
    FILE *fp = fopen("/proc/meminfo", "r");
    if (fp == NULL)
    {
        printf("[INFO] /proc/meminfo not available (needs CONFIG_FS_PROCFS)\n");
    }
    else
    {
        char line[256];
        /* Skip header line */
        if (fgets(line, sizeof(line), fp))
        {
            printf("[INFO] Heap usage (from /proc/meminfo):\n");
            while (fgets(line, sizeof(line), fp))
            {
                unsigned long total, used, free_ul, maxused, maxfree;
                unsigned long nused, nfree;
                char name[32];
                int n = sscanf(line, "%lu%lu%lu%lu%lu%lu%lu %31s",
                               &total, &used, &free_ul, &maxused,
                               &maxfree, &nused, &nfree, name);
                if (n >= 8)
                {
                    printf("[INFO]   %s: total=%lu KB  used=%lu KB  free=%lu KB  "
                           "nused=%lu  nfree=%lu\n",
                           name, total / 1024, used / 1024, free_ul / 1024,
                           nused, nfree);
                }
            }
        }
        else
        {
            printf("[INFO] /proc/meminfo: empty or unreadable\n");
        }
        fclose(fp);
    }

    /* Open framebuffer */
    int fd = open(FB_DEVICE, O_RDWR);
    if (fd < 0)
    {
        printf("[FAIL] Cannot open %s: errno=%d\n", FB_DEVICE, errno);
        return 1;
    }
    printf("[INFO] Opened %s (fd=%d)\n", FB_DEVICE, fd);

    /* Get video info */
    struct fb_videoinfo_s vinfo;
    memset(&vinfo, 0, sizeof(vinfo));
    if (ioctl(fd, FBIOGET_VIDEOINFO, (unsigned long)(uintptr_t)&vinfo) < 0)
    {
        printf("[FAIL] FBIOGET_VIDEOINFO failed: errno=%d\n", errno);
        close(fd);
        return 1;
    }

    const char *fmt_str = "UNKNOWN";
    switch (vinfo.fmt)
    {
        case FB_FMT_RGB32:   fmt_str = "RGB32 (XRGB8888)"; break;
        case FB_FMT_RGB24:   fmt_str = "RGB24";            break;
        case FB_FMT_RGB16_565: fmt_str = "RGB565";         break;
        case FB_FMT_RGBA32:  fmt_str = "RGBA32";           break;
        case FB_FMT_YUV420:  fmt_str = "YUV420";           break;
        case FB_FMT_YUV422:  fmt_str = "YUV422";           break;
    }
    printf("[INFO] VideoInfo: fmt=%u (%s)  xres=%u  yres=%u  nplanes=%u\n",
           vinfo.fmt, fmt_str, vinfo.xres, vinfo.yres, vinfo.nplanes);

    /* Get plane info */
    struct fb_planeinfo_s pinfo;
    memset(&pinfo, 0, sizeof(pinfo));
    if (ioctl(fd, FBIOGET_PLANEINFO, (unsigned long)(uintptr_t)&pinfo) < 0)
    {
        printf("[FAIL] FBIOGET_PLANEINFO failed: errno=%d\n", errno);
        close(fd);
        return 1;
    }
    printf("[INFO] PlaneInfo: fbmem=%p  fblen=%zu bytes (%.1f MB)\n",
           pinfo.fbmem, pinfo.fblen, (float)pinfo.fblen / (1024 * 1024));
    printf("[INFO]   stride=%u bytes  bpp=%u  display=%u\n",
           pinfo.stride, pinfo.bpp, pinfo.display);
    printf("[INFO]   virtual=%ux%u  offset=%ux%u\n",
           pinfo.xres_virtual, pinfo.yres_virtual,
           pinfo.xoffset, pinfo.yoffset);

    /* Calculate expected buffer sizes */
    uint32_t expected_single = vinfo.xres * vinfo.yres * (pinfo.bpp / 8);
    uint32_t expected_stride = vinfo.xres * (pinfo.bpp / 8);
    printf("[INFO] Calculated: single_buffer=%.1f MB  expected_stride=%u\n",
           (float)expected_single / (1024 * 1024), expected_stride);

    if (pinfo.stride != expected_stride)
        printf("[INFO] WARNING: stride mismatch (hw=%u calc=%u) - may have padding\n",
               pinfo.stride, expected_stride);

    /* Extra buffer/overlay check */
    if (pinfo.fblen >= expected_single * 2)
        printf("[INFO] fblen >= 2x single buffer → likely double-buffered\n");
    else
        printf("[INFO] fblen ~= single buffer → likely single-buffered\n");

    /* Try to get framerate */
    int framerate = 0;
    if (ioctl(fd, FBIOGET_FRAMERATE, (unsigned long)(uintptr_t)&framerate) < 0)
    {
        printf("[INFO] FBIOGET_FRAMERATE: not supported\n");
    }
    else
    {
        printf("[INFO] Framerate: %d fps\n", framerate);
    }

    /* Summary */
    printf("[INFO] SUMMARY: xres=%u yres=%u fmt=%s bpp=%u stride=%u\n",
           vinfo.xres, vinfo.yres, fmt_str, pinfo.bpp, pinfo.stride);

    close(fd);
    printf("[PASS] Info test completed\n");
    return 0;
}

/****************************************************************************/

static int run_mode_raw(void)
{
    printf("===== [RAW] Raw Framebuffer Test (bypass LVGL) =====\n");

    int fd = open(FB_DEVICE, O_RDWR);
    if (fd < 0)
    {
        printf("[FAIL] Cannot open %s: errno=%d\n", FB_DEVICE, errno);
        return 1;
    }

    struct fb_videoinfo_s vinfo;
    struct fb_planeinfo_s pinfo;
    memset(&vinfo, 0, sizeof(vinfo));
    memset(&pinfo, 0, sizeof(pinfo));

    if (ioctl(fd, FBIOGET_VIDEOINFO, (unsigned long)(uintptr_t)&vinfo) < 0)
    {
        printf("[FAIL] FBIOGET_VIDEOINFO failed: errno=%d\n", errno);
        close(fd);
        return 1;
    }

    if (ioctl(fd, FBIOGET_PLANEINFO, (unsigned long)(uintptr_t)&pinfo) < 0)
    {
        printf("[FAIL] FBIOGET_PLANEINFO failed: errno=%d\n", errno);
        close(fd);
        return 1;
    }

    printf("[RAW] Display: %ux%u  bpp=%u  stride=%u  fblen=%zu\n",
           vinfo.xres, vinfo.yres, pinfo.bpp, pinfo.stride, pinfo.fblen);

    if (pinfo.bpp != 32)
    {
        printf("[FAIL] Raw test requires 32bpp, got %u bpp\n", pinfo.bpp);
        close(fd);
        return 1;
    }

    /* mmap framebuffer */
    FAR uint32_t *fbmem = (FAR uint32_t *)mmap(NULL, pinfo.fblen,
                                               PROT_READ | PROT_WRITE,
                                               MAP_SHARED | MAP_FILE, fd, 0);
    if (fbmem == MAP_FAILED)
    {
        printf("[FAIL] mmap failed: errno=%d\n", errno);
        close(fd);
        return 1;
    }
    printf("[RAW] mmap ok: fbmem=%p  size=%.1f MB\n",
           (void *)fbmem, (float)pinfo.fblen / (1024 * 1024));

    /* Phase A: Solid RED */
    printf("[RAW] Phase A: Fill RED — verify uniform color, no artifacts\n");
    raw_fill_screen(fbmem, pinfo.stride, vinfo.xres, vinfo.yres, RAW_RED);
    printf("[RAW] Phase A: done. Look for: any dark spots / lines / wrong colors?\n");
    usleep(2000 * 1000);

    /* Phase B: Solid GREEN */
    printf("[RAW] Phase B: Fill GREEN\n");
    raw_fill_screen(fbmem, pinfo.stride, vinfo.xres, vinfo.yres, RAW_GREEN);
    printf("[RAW] Phase B: done. Look for: any artifacts?\n");
    usleep(2000 * 1000);

    /* Phase C: Solid BLUE */
    printf("[RAW] Phase C: Fill BLUE\n");
    raw_fill_screen(fbmem, pinfo.stride, vinfo.xres, vinfo.yres, RAW_BLUE);
    printf("[RAW] Phase C: done. Look for: any artifacts?\n");
    usleep(2000 * 1000);

    /* Phase D: Color bars */
    printf("[RAW] Phase D: 8 color bars (R,G,B,W,Black,Yellow,Cyan,Magenta)\n");
    raw_draw_bars(fbmem, pinfo.stride, vinfo.xres, vinfo.yres);
    printf("[RAW] Phase D: done. Verify: all 8 bars visible? Colors correct? "
           "Bar boundaries clean?\n");
    usleep(3000 * 1000);

    /* Phase E: Border test */
    printf("[RAW] Phase E: White border on black background\n");
    raw_draw_border(fbmem, pinfo.stride, vinfo.xres, vinfo.yres, RAW_WHITE);
    printf("[RAW] Phase E: done. Verify: 1px white border on ALL 4 edges? "
           "Any edge missing?\n");
    usleep(3000 * 1000);

    /* Cleanup */
    munmap(fbmem, pinfo.fblen);
    close(fd);

    printf("[PASS] Raw framebuffer test completed\n");
    printf("[RAW] DIAGNOSIS:\n");
    printf("[RAW]   If ALL phases displayed correctly → display DRIVER is OK, "
           "problem is in LVGL layer\n");
    printf("[RAW]   If solid colors have artifacts → driver/power/timing issue\n");
    printf("[RAW]   If border missing on edges → DSI timing or DE line limit\n");
    printf("[RAW]   If color bars have wrong colors → pixel format mismatch\n");
    return 0;
}

/****************************************************************************/

static void draw_test_pattern(void)
{
    lv_obj_t *scr = lv_scr_act();
    lv_obj_set_style_bg_color(scr, lv_color_hex(0x000000), 0);

    /* Draw grid of color blocks */
    for (int row = 0; row < GRID_ROWS; row++)
    {
        for (int col = 0; col < GRID_COLS; col++)
        {
            lv_obj_t *rect = lv_obj_create(scr);
            lv_obj_set_size(rect, CELL_W - 2, CELL_H - 2);
            lv_obj_set_pos(rect, col * CELL_W + 1, row * CELL_H + 1);
            lv_obj_set_style_bg_color(rect, grid_colors[row][col], 0);
            lv_obj_set_style_border_width(rect, 0, 0);
            lv_obj_set_style_radius(rect, 0, 0);
            lv_obj_clear_flag(rect, LV_OBJ_FLAG_SCROLLABLE);

            lv_obj_t *label = lv_label_create(rect);
            lv_label_set_text_fmt(label, "%d,%d\n(%dx%d)",
                col, row, CELL_W, CELL_H);
            lv_obj_set_style_text_color(label,
                (row == 2 && col == 2) ? lv_color_hex(0xFFFFFF) : lv_color_hex(0x000000), 0);
            lv_obj_set_style_text_font(label, &lv_font_montserrat_16, 0);
            lv_obj_center(label);
        }
    }

    /* Title */
    lv_obj_t *title = lv_label_create(scr);
    lv_label_set_text_fmt(title, "6FHD Screen Test: %dx%d", SCREEN_WIDTH, SCREEN_HEIGHT);
    lv_obj_set_style_text_color(title, lv_color_hex(0xFFFFFF), 0);
    lv_obj_set_style_text_font(title, &lv_font_montserrat_48, 0);
    lv_obj_align(title, LV_ALIGN_CENTER, 0, -20);

    /* Info */
    lv_obj_t *info = lv_label_create(scr);
    lv_label_set_text(info, "Check all color blocks are visible\n"
                            "Center should show coordinates\n"
                            "Press 'q' then Enter to exit");
    lv_obj_set_style_text_color(info, lv_color_hex(0xFFFF00), 0);
    lv_obj_set_style_text_font(info, &lv_font_montserrat_16, 0);
    lv_obj_align(info, LV_ALIGN_CENTER, 0, 30);
}

static int run_mode_lvgl(void)
{
    printf("===== [LVGL] LVGL Test with Memory Monitor =====\n");

    printf("[LVGL] Initializing lv_init()...\n");
    lv_init();

    /* Baseline memory */
    lv_mem_monitor_t mem;
    lv_mem_monitor(&mem);
    printf("[MEM] Before LVGL display init:\n");
    printf("[MEM]   total=%zu KB  free=%zu KB  used_pct=%u%%  frag_pct=%u%%\n",
           mem.total_size / 1024, mem.free_size / 1024,
           mem.used_pct, mem.frag_pct);
    printf("[MEM]   max_used=%zu KB  free_biggest=%zu KB  "
           "free_cnt=%zu  used_cnt=%zu\n",
           mem.max_used / 1024, mem.free_biggest_size / 1024,
           mem.free_cnt, mem.used_cnt);

    /* Initialize NuttX display driver */
    lv_nuttx_dsc_t info;
    lv_nuttx_result_t result;
    lv_nuttx_dsc_init(&info);
#ifdef CONFIG_LV_USE_NUTTX_LCD
    info.fb_path = "/dev/lcd0";
#endif
#ifdef CONFIG_INPUT_TOUCHSCREEN
    info.input_path = "/dev/input0";
#endif

    printf("[LVGL] Calling lv_nuttx_init() with fb_path=%s input_path=%s...\n",
           info.fb_path ? info.fb_path : "(default)",
           info.input_path ? info.input_path : "(none)");

    lv_nuttx_init(&info, &result);

    if (result.disp == NULL)
    {
        printf("[FAIL] lv_nuttx_init() returned NULL display!\n");
        printf("[FAIL] Check: is /dev/lcd0 available? Is LCD driver loaded?\n");
        return 1;
    }

    /* Display info */
    int32_t hor = lv_display_get_horizontal_resolution(NULL);
    int32_t ver = lv_display_get_vertical_resolution(NULL);
    printf("[LVGL] Display initialized: %" PRId32 "x%" PRId32 "\n", hor, ver);
    printf("[PASS] Display driver connected successfully\n");

    /* Memory after init */
    lv_mem_monitor(&mem);
    printf("[MEM] After LVGL display init:\n");
    printf("[MEM]   total=%zu KB  free=%zu KB  used_pct=%u%%  frag_pct=%u%%\n",
           mem.total_size / 1024, mem.free_size / 1024,
           mem.used_pct, mem.frag_pct);

    if (mem.frag_pct > 50)
        printf("[MEM] WARNING: High fragmentation (%u%%) — may cause allocation failures\n",
               mem.frag_pct);

    if (mem.free_size < 256 * 1024)
        printf("[MEM] WARNING: Low free memory (%zu KB) — may cause partial draw failures\n",
               mem.free_size / 1024);

    /* Draw test pattern */
    printf("[LVGL] Drawing 3x4 color grid test pattern...\n");
    draw_test_pattern();

    lv_mem_monitor(&mem);
    printf("[MEM] After drawing test pattern:\n");
    printf("[MEM]   total=%zu KB  free=%zu KB  used_pct=%u%%  frag_pct=%u%%\n",
           mem.total_size / 1024, mem.free_size / 1024,
           mem.used_pct, mem.frag_pct);

    /* Main loop with periodic memory monitoring */
    printf("[LVGL] Entering main loop. Press 'q'+Enter to exit.\n");
    printf("[LVGL] Memory stats printed every ~300 iterations (~5 seconds).\n");

    uint32_t iterations = 0;
    while (1)
    {
        uint32_t idle = lv_timer_handler();
        idle = idle ? idle : 1;
        usleep(idle * 1000);

        iterations++;

        /* Periodic memory dump */
        if (iterations % 300 == 0)
        {
            lv_mem_monitor(&mem);
            printf("[LVGL] iter=%u  used_pct=%u%%  frag_pct=%u%%  "
                   "free=%zu KB  max_used=%zu KB\n",
                   iterations, mem.used_pct, mem.frag_pct,
                   mem.free_size / 1024, mem.max_used / 1024);

            /* Alert if memory is degrading */
            if (mem.frag_pct > 80)
                printf("[MEM] CRITICAL: fragmentation > 80%% — likely cause of corruption!\n");
        }

        /* Non-blocking stdin check for exit */
        {
            struct timeval tv = { 0, 0 };
            fd_set fds;
            FD_ZERO(&fds);
            FD_SET(STDIN_FILENO, &fds);
            if (select(STDIN_FILENO + 1, &fds, NULL, NULL, &tv) > 0)
            {
                char c;
                if (read(STDIN_FILENO, &c, 1) > 0 && c == 'q')
                {
                    printf("[LVGL] User requested exit (q pressed)\n");
                    break;
                }
            }
        }
    }

    /* Final memory stats */
    lv_mem_monitor(&mem);
    printf("[MEM] Final: total=%zu KB  free=%zu KB  used_pct=%u%%  frag_pct=%u%%\n",
           mem.total_size / 1024, mem.free_size / 1024,
           mem.used_pct, mem.frag_pct);

    /* Cleanup */
    printf("[LVGL] Deinitializing...\n");
    lv_nuttx_deinit(&result);
    lv_deinit();

    printf("[PASS] LVGL test completed\n");
    return 0;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
    if (argc >= 2)
    {
        if (strcmp(argv[1], "info") == 0)
        {
            return run_mode_info();
        }
        else if (strcmp(argv[1], "raw") == 0)
        {
            return run_mode_raw();
        }
        else if (strcmp(argv[1], "lvgl") == 0)
        {
            return run_mode_lvgl();
        }
        else if (strcmp(argv[1], "all") == 0)
        {
            goto run_all;
        }
        else
        {
            printf("Usage: screentest [info|raw|lvgl|all]\n");
            printf("  info  — Dump system/display info\n");
            printf("  raw   — Raw framebuffer test (bypass LVGL, diagnose driver)\n");
            printf("  lvgl  — LVGL color grid + memory monitor\n");
            printf("  all   — Run all tests sequentially\n");
            printf("  (no args = all)\n");
            return 1;
        }
    }
    else
    {
run_all:
        printf("===== Running ALL tests sequentially =====\n\n");
        if (run_mode_info() != 0)
        {
            printf("\n[FAIL] Info test failed — continuing anyway\n");
        }
        printf("\n");
        if (run_mode_raw() != 0)
        {
            printf("\n[FAIL] Raw test failed — continuing anyway\n");
        }
        printf("\n");
        if (run_mode_lvgl() != 0)
        {
            printf("\n[FAIL] LVGL test failed\n");
        }
        printf("\n===== All tests complete =====\n");
    }

    return 0;
}

