762		lcd_dev[sel]->tcon0_basic0.bits.x = panel->lcd_x - 1;
763		lcd_dev[sel]->tcon0_basic0.bits.y = panel->lcd_y - 1;
764		lcd_dev[sel]->tcon0_basic1.bits.ht = panel->lcd_ht - 1;
765		lcd_dev[sel]->tcon0_basic1.bits.hbp =
766		    (panel->lcd_hbp == 0) ? 0 : panel->lcd_hbp - 1;
767		lcd_dev[sel]->tcon0_basic2.bits.vt = panel->lcd_vt * 2;
768		lcd_dev[sel]->tcon0_basic2.bits.vbp =
769		    (panel->lcd_vbp == 0) ? 0 : panel->lcd_vbp - 1;
770		lcd_dev[sel]->tcon0_basic3.bits.hspw =
771		    (panel->lcd_hspw == 0) ? 0 : panel->lcd_hspw - 1;
772		lcd_dev[sel]->tcon0_basic3.bits.vspw =
773		    (panel->lcd_vspw == 0) ? 0 : panel->lcd_vspw - 1;
774		start_delay = panel->lcd_vt - panel->lcd_y - 8;
775		if (panel->lcd_hv_if == LCD_HV_IF_CCIR656_2CYC) {
776			if (panel->lcd_interlace) {
777				lcd_dev[sel]->tcon0_basic0.bits.y =
778				    panel->lcd_y / 2 - 1;
779				lcd_dev[sel]->tcon0_basic2.bits.vt =
780				    (panel->lcd_hv_syuv_fdly ==
781				     LCD_HV_SRGB_FDLY_2LINE) ? 525 : 625;
782				start_delay = panel->lcd_vt / 2 - panel->lcd_y / 2 - 10;
783			} else {
784				lcd_dev[sel]->tcon0_basic0.bits.y = panel->lcd_y - 1;
785				lcd_dev[sel]->tcon0_basic2.bits.vt =
786				    (panel->lcd_hv_syuv_fdly ==
787				     LCD_HV_SRGB_FDLY_2LINE) ? 1050 : 1250;
788			}
789	
790			lcd_dev[sel]->tcon0_basic1.bits.ht =
791			    (panel->lcd_ht == 0) ? 0 : (panel->lcd_ht * 2 - 1);
792			lcd_dev[sel]->tcon0_basic1.bits.hbp =
793			    (panel->lcd_hbp == 0) ? 0 : (panel->lcd_hbp * 2 - 1);
794			lcd_dev[sel]->tcon0_basic3.bits.hspw =
795			    (panel->lcd_hspw == 0) ? 0 : (panel->lcd_hspw * 2 - 1);
796		}
797		if (start_delay < 10)
798			start_delay = 10;
799		else if (start_delay > 31)
800			start_delay = 31;
