static void raw_fill_screen(FAR uint32_t *fbmem, fb_coord_t stride,
                            fb_coord_t xres, fb_coord_t yres, uint32_t color)
{
    uint32_t stride_words = stride / 4;

    /* Fast path: if color is black (0x00000000) or white (0xFFFFFFFF),
     * use memset which is highly optimized (STM loops, possibly NEON) */
    if (color == 0x00000000 || color == 0xFFFFFFFF)
    {
        uint8_t byte_val = (uint8_t)(color & 0xFF);
        for (fb_coord_t y = 0; y < yres; y++)
        {
            memset((uint8_t *)fbmem + y * stride, byte_val, xres * 4);
        }
        return;
    }

    /* General path: fill entire framebuffer as flat array (includes padding),
     * single loop for better compiler optimization */
    uint32_t total_words = stride_words * yres;
    for (uint32_t i = 0; i < total_words; i++)
    {
        fbmem[i] = color;
    }
}

