static void raw_fill_screen(FAR uint32_t *fbmem, fb_coord_t stride,
                            fb_coord_t xres, fb_coord_t yres, uint32_t color)
{
    /* Use bulk memset per row for maximum DDR write efficiency.
     * Avoids pixel-by-pixel overhead: ARM will use STM/LDM burst. */
    uint32_t row_bytes = xres * 4;

    /* Pre-fill a single row buffer and memcpy it across */
    FAR uint32_t *row_buf = (FAR uint32_t *)malloc(row_bytes);
    if (row_buf == NULL)
    {
        /* Fallback: direct fill including padding for speed */
        uint32_t stride_words = stride / 4;
        uint32_t total = stride_words * yres;
        for (uint32_t i = 0; i < total; i++)
            fbmem[i] = color;
        return;
    }

    for (uint32_t i = 0; i < xres; i++)
        row_buf[i] = color;

    for (fb_coord_t y = 0; y < yres; y++)
    {
        memcpy((uint8_t *)fbmem + y * stride, row_buf, row_bytes);
    }

    free(row_buf);
}

