static void lvgl_clean_screen(void)
{
    lv_obj_t *scr = lv_scr_act();
    lv_obj_clean(scr);
    lv_obj_remove_style_all(scr);
    lv_obj_set_style_border_width(scr, 0, 0);
    lv_obj_set_scrollbar_mode(scr, LV_SCROLLBAR_MODE_OFF);
}

static void lvgl_flush_and_wait(uint32_t ms)
{
    uint32_t elapsed = 0;
    while (elapsed < ms)
    {
        uint32_t idle = lv_timer_handler();
        idle = idle ? idle : 1;
        uint32_t delay = (idle < ms - elapsed) ? idle : (ms - elapsed);
        usleep(delay * 1000);
        elapsed += delay;
    }
}

