/****************************************************************************
 * apps/examples/desktop_companion/hal_api.h
 *
 * HAL Hardware Abstraction Layer — Sensor & Audio Interface
 * Stub implementations for build verification; replace with real drivers.
 ****************************************************************************/

#ifndef HAL_API_H
#define HAL_API_H

#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>

/* ── Sensor API (LTR553 & SHTC3) ─────────────────────────────────────── */

/** Get proximity sensor data.
 *  @param[out] distance    Raw proximity value (0 = near, larger = far)
 *  @param[out] is_present  Algorithm result: true = person detected nearby
 */
void hal_sensor_get_proximity(uint16_t *distance, bool *is_present);

/** Get environmental sensor data.
 *  @param[out] temp  Temperature in degrees Celsius (°C)
 *  @param[out] hum   Relative humidity (0.0 ~ 100.0 %)
 *  @param[out] lux   Ambient light intensity in Lux
 */
void hal_sensor_get_env(float *temp, float *hum, uint32_t *lux);

/* ── Audio API (ES8156 & Mic) ────────────────────────────────────────── */

/** Type for PCM audio data callback (invoked from audio IRQ / worker). */
typedef void (*hal_audio_data_cb_t)(const uint8_t *buffer, size_t len);

/** Start microphone capture.
 *  @param on_pcm_data  Callback fired for each PCM chunk; MUST be
 *                      non-blocking and keep the buffer valid only
 *                      during the call.
 */
void hal_audio_mic_start(hal_audio_data_cb_t on_pcm_data);

/** Stop microphone capture. */
void hal_audio_mic_stop(void);

/** Queue PCM data for speaker playback (non-blocking).
 *  The implementation MUST copy the buffer internally or DMA it;
 *  the caller may free @p buffer immediately after return.
 */
void hal_audio_speaker_play(const uint8_t *buffer, size_t len);

/** Check whether the speaker is currently playing. */
bool hal_audio_speaker_is_playing(void);

/* ── Stub sensors for bring‑up ──────────────────────────────────────────
 *  Define HAL_USE_STUB_SENSORS to get dummy implementations that let
 *  the UI run without actual sensor hardware connected.
 ****************************************************************************/
#ifdef HAL_USE_STUB_SENSORS
static inline void hal_stub_init(void)
{
    /* nothing */
}
#endif /* HAL_USE_STUB_SENSORS */

#endif /* HAL_API_H */

/****************************************************************************
 * apps/examples/desktop_companion/app_core.h
 *
 * Core Application State Machine — Data-Control Layer
 ****************************************************************************/

#ifndef APP_CORE_H
#define APP_CORE_H

#include <stdint.h>
#include <stdbool.h>

/* ── Pet FSM states ──────────────────────────────────────────────────── */

typedef enum {
    PET_AWAKE,      /* Normal: eyes open, proximity = near */
    PET_SLEEPING,   /* Away > 5 s: eyes closed, slow breathe */
    PET_HAPPY,      /* Just arrived: big smile, fast breathe (3 s then → AWAKE) */
} pet_state_t;

typedef enum {
    AI_IDLE,        /* Mic off */
    AI_LISTENING,   /* Mic on, capturing */
    AI_THINKING,    /* Processing on server/device */
    AI_SPEAKING,    /* TTS playback active */
} ai_state_t;

/* ── Global application state ────────────────────────────────────────── */

typedef struct {
    /* Zone 1 — Status bar */
    struct {
        int  hour;
        int  minute;
        int  second;
        int  year;
        int  month;
        int  day;
        int  weekday;
        float temperature;          /* °C (SHTC3) */
        float humidity;             /* %   (SHTC3) */
        uint32_t lux;               /* Lux (LTR553) */
        bool  wifi_connected;
    } status;

    /* Zone 2 — Pet */
    struct {
        uint16_t  proximity_raw;    /* LTR553 raw */
        bool      person_present;   /* filtered */
        pet_state_t state;
        uint32_t  happy_timer;      /* countdown ticks before →AWAKE */
    } pet;

    /* Zone 3 — AI / Chat */
    struct {
        ai_state_t state;
        char      status_text[40];
        char      dialog_buf[1024]; /* ring of last text */
    } ai;

    /* Zone 4 — Health */
    struct {
        uint32_t  sit_seconds;      /* 0..2700 (45 min) */
        uint32_t  drink_seconds;    /* 0..3600 (60 min) */
        bool      sit_alert;
        bool      drink_alert;
    } health;

    /* Internal book‑keeping */
    uint32_t  tick_count;           /* seconds since app start */
} app_state_t;

/* ── Public API ──────────────────────────────────────────────────────── */

/** One‑time initialisation.
 *  Creates the LVGL timer that drives the state machine.
 *  Must be called after lv_init() and lv_nuttx_init().
 */
void app_core_init(void);

/** Returns a read‑only pointer to the current state.
 *  UI layer reads this in its update routines; never write directly.
 */
const app_state_t *app_core_get_state(void);

/** Force‑set the AI conversation text (called from speech‑recv callback). */
void app_core_set_ai_text(const char *text);

/** Force‑set the AI state (called from speech pipeline). */
void app_core_set_ai_state(ai_state_t s);

/** Mark that the user just drank water (resets drink timer). */
void app_core_drink_reset(void);

/** Mark that the user stood up / reset sit timer. */
void app_core_sit_reset(void);

#endif /* APP_CORE_H */

/****************************************************************************
 * apps/examples/desktop_companion/app_core.c
 *
 * Core Application State Machine
 ****************************************************************************/

#include <nuttx/config.h>
#include <string.h>
#include <stdio.h>
#include <lvgl/lvgl.h>

#include "app_core.h"
#include "ui_main.h"
#include "hal_api.h"

/* ── Tunables ────────────────────────────────────────────────────────── */

#define TICK_MS             1000    /* 1 second per tick */
#define SIT_THRESHOLD_S     2700    /* 45 min = 2700 s */
#define DRINK_THRESHOLD_S   3600    /* 60 min = 3600 s */
#define SLEEP_HYSTERESIS_S  5       /* person away this many ticks → SLEEP */
#define HAPPY_DURATION_S    3       /* keep HAPPY face this many ticks */

/* ── Private state ───────────────────────────────────────────────────── */

static app_state_t  g_state;
static bool         g_dirty;                 /* any field changed this tick */
static bool         g_pet_dirty;             /* pet state / proximity changed */
static bool         g_zone1_dirty;           /* status bar changed */
static bool         g_zone3_dirty;           /* AI text / state changed */
static bool         g_zone4_dirty;           /* health changed */

/* ── Forward declarations ────────────────────────────────────────────── */

static void app_timer_cb(lv_timer_t *timer);

/* ── Initialisation ──────────────────────────────────────────────────── */

void app_core_init(void)
{
    memset(&g_state, 0, sizeof(g_state));
    g_state.pet.state          = PET_AWAKE;
    g_state.ai.state           = AI_IDLE;
    strcpy(g_state.ai.status_text, "[mic idle]");

    g_dirty = g_pet_dirty = g_zone1_dirty = g_zone3_dirty = g_zone4_dirty = true;

    /* Create 1‑second LVGL timer — auto‑integrated with libuv. */
    lv_timer_create(app_timer_cb, TICK_MS, NULL);
}

/* ── State accessors ─────────────────────────────────────────────────── */

const app_state_t *app_core_get_state(void)
{
    return &g_state;
}

void app_core_set_ai_text(const char *text)
{
    /* Append to ring buffer */
    size_t cur = strlen(g_state.ai.dialog_buf);
    size_t tlen = strlen(text);
    if (cur + tlen + 3 > sizeof(g_state.ai.dialog_buf))
    {
        /* Evict oldest half */
        char *p = g_state.ai.dialog_buf;
        char *mid = p + sizeof(g_state.ai.dialog_buf) / 2;
        while (*mid) *p++ = *mid++;
        *p = '\0';
        cur = strlen(g_state.ai.dialog_buf);
    }
    if (cur > 0) { strcat(g_state.ai.dialog_buf, "\n"); cur++; }
    strcat(g_state.ai.dialog_buf, text);

    g_zone3_dirty = true;
}

void app_core_set_ai_state(ai_state_t s)
{
    if (g_state.ai.state == s) return;
    g_state.ai.state = s;
    switch (s)
    {
        case AI_IDLE:      snprintf(g_state.ai.status_text, sizeof(g_state.ai.status_text), "[mic idle]");       break;
        case AI_LISTENING: snprintf(g_state.ai.status_text, sizeof(g_state.ai.status_text), "[listening...]");   break;
        case AI_THINKING:  snprintf(g_state.ai.status_text, sizeof(g_state.ai.status_text), "[thinking...]");    break;
        case AI_SPEAKING:  snprintf(g_state.ai.status_text, sizeof(g_state.ai.status_text), "[speaking...]");    break;
    }
    g_zone3_dirty = true;
}

void app_core_drink_reset(void)
{
    g_state.health.drink_seconds  = 0;
    g_state.health.drink_alert    = false;
    g_zone4_dirty = true;
}

void app_core_sit_reset(void)
{
    g_state.health.sit_seconds    = 0;
    g_state.health.sit_alert      = false;
    g_zone4_dirty = true;
}

/* ── Pet FSM update ──────────────────────────────────────────────────── */

static void update_pet(bool person_present)
{
    switch (g_state.pet.state)
    {
    case PET_AWAKE:
        if (!person_present)
        {
            /* Start counting away‑time */
            g_state.pet.happy_timer++;
            if (g_state.pet.happy_timer >= SLEEP_HYSTERESIS_S)
            {
                g_state.pet.state = PET_SLEEPING;
                g_state.pet.happy_timer = 0;
                g_pet_dirty = true;
            }
        }
        else
        {
            g_state.pet.happy_timer = 0; /* reset away‑counter */
        }
        break;

    case PET_SLEEPING:
        if (person_present)
        {
            /* Person just arrived → HAPPY for a few seconds */
            g_state.pet.state       = PET_HAPPY;
            g_state.pet.happy_timer = HAPPY_DURATION_S;
            g_pet_dirty = true;
        }
        break;

    case PET_HAPPY:
        if (g_state.pet.happy_timer > 0)
        {
            g_state.pet.happy_timer--;
        }
        if (g_state.pet.happy_timer == 0)
        {
            g_state.pet.state = person_present ? PET_AWAKE : PET_SLEEPING;
            g_pet_dirty = true;
        }
        /* If person left while happy, transition normally */
        break;
    }
}

/* ── Health timers ───────────────────────────────────────────────────── */

static void update_health(void)
{
    bool dirty_local = false;

    if (g_state.health.sit_seconds < SIT_THRESHOLD_S)
    {
        g_state.health.sit_seconds++;
        if (g_state.health.sit_seconds >= SIT_THRESHOLD_S)
        {
            g_state.health.sit_alert = true;
        }
        dirty_local = true;
    }

    if (g_state.health.drink_seconds < DRINK_THRESHOLD_S)
    {
        g_state.health.drink_seconds++;
        if (g_state.health.drink_seconds >= DRINK_THRESHOLD_S)
        {
            g_state.health.drink_alert = true;
        }
        dirty_local = true;
    }

    if (dirty_local) g_zone4_dirty = true;
}

/* ── Zone‑1 clock & env update ───────────────────────────────────────── */

static void update_clock_and_env(void)
{
    /* TODO: replace with proper RTC time‑of‑day call */
    /* For now: increment simulated time every tick (1 s) */
    g_state.status.second++;
    if (g_state.status.second >= 60)
    {
        g_state.status.second = 0;
        g_state.status.minute++;
        if (g_state.status.minute >= 60)
        {
            g_state.status.minute = 0;
            g_state.status.hour   = (g_state.status.hour + 1) % 24;
        }
    }

    /* Poll HAL sensors (non‑blocking stubs for now) */
    {
        uint16_t dist;
        bool     present;
        float    t, h;
        uint32_t lx;

        hal_sensor_get_proximity(&dist, &present);
        hal_sensor_get_env(&t, &h, &lx);

        if (g_state.pet.proximity_raw != dist)
        {
            g_state.pet.proximity_raw = dist;
            g_pet_dirty = true;
        }
        /* Person‑present: hysteresis inside pet FSM */
        g_state.pet.person_present = present;

        if (g_state.status.temperature != t ||
            g_state.status.humidity    != h ||
            g_state.status.lux         != lx)
        {
            g_state.status.temperature = t;
            g_state.status.humidity    = h;
            g_state.status.lux         = lx;
            g_zone1_dirty = true;
        }
    }

    g_zone1_dirty = true; /* clock always advances */
}

/* ── LVGL timer callback ─────────────────────────────────────────────── */

static void app_timer_cb(lv_timer_t *timer)
{
    (void)timer;

    g_state.tick_count++;

    /* 1. Clock + Environment (Zone 1) */
    update_clock_and_env();

    /* 2. Pet FSM (Zone 2) */
    update_pet(g_state.pet.person_present);

    /* 3. Health timers (Zone 4) */
    update_health();

    /* 4. Flush all dirty flags to UI layer */
    if (g_zone1_dirty || g_dirty)  ui_main_update_zone1(&g_state);
    if (g_pet_dirty  || g_dirty)   ui_main_update_zone2(&g_state);
    if (g_zone3_dirty || g_dirty)  ui_main_update_zone3(&g_state);
    if (g_zone4_dirty || g_dirty)  ui_main_update_zone4(&g_state);

    g_dirty = g_zone1_dirty = g_pet_dirty = g_zone3_dirty = g_zone4_dirty = false;
}

/****************************************************************************
 * apps/examples/desktop_companion/ui_main.h
 *
 * UI View Layer — Pure rendering, reads state from app_core.
 ****************************************************************************/

#ifndef UI_MAIN_H
#define UI_MAIN_H

#include "app_core.h"

/* ── One‑time screen creation ────────────────────────────────────────── */

/** Create the full 4‑zone UI layout.
 *  Must be called once after lv_nuttx_init().
 */
void ui_main_create(void);

/* ── Incremental zone updates ────────────────────────────────────────── */

/** Refresh Zone 1 — clock, env, WiFi icon. */
void ui_main_update_zone1(const app_state_t *state);

/** Refresh Zone 2 — pet face & breathe animation. */
void ui_main_update_zone2(const app_state_t *state);

/** Refresh Zone 3 — AI status & dialog. */
void ui_main_update_zone3(const app_state_t *state);

/** Refresh Zone 4 — health reminders. */
void ui_main_update_zone4(const app_state_t *state);

#endif /* UI_MAIN_H */

/****************************************************************************
 * apps/examples/desktop_companion/ui_main.c
 *
 * UI View Layer — 4‑Zone card layout for 1080 × 2160 portrait screen.
 ****************************************************************************/

#include <nuttx/config.h>
#include <string.h>
#include <stdio.h>
#include <lvgl/lvgl.h>

#include "ui_main.h"
#include "app_core.h"

/* ── Zone geometry (hard‑coded for 1080 × 2160) ──────────────────────── */

#define Z1_Y     0
#define Z1_H   400

#define Z2_Y   400
#define Z2_H   900

#define Z3_Y  1300
#define Z3_H   500

#define Z4_Y  1800
#define Z4_H   360

/* ── Colour palette ──────────────────────────────────────────────────── */

#define CLR_BG       LV_COLOR_MAKE(0x0F, 0x0F, 0x23)   /* dark navy    */
#define CLR_Z1_BG    LV_COLOR_MAKE(0x1A, 0x1A, 0x2E)
#define CLR_Z2_BG    LV_COLOR_MAKE(0x16, 0x16, 0x28)
#define CLR_Z3_BG    LV_COLOR_MAKE(0x12, 0x12, 0x26)
#define CLR_Z4_BG    LV_COLOR_MAKE(0x0A, 0x0A, 0x20)
#define CLR_ACCENT   LV_COLOR_MAKE(0x00, 0xBF, 0xFF)   /* cyan accent  */
#define CLR_TEXT     LV_COLOR_MAKE(0xE0, 0xE0, 0xE0)   /* light grey   */
#define CLR_TEXT_DIM LV_COLOR_MAKE(0x80, 0x80, 0x90)
#define CLR_ALERT    LV_COLOR_MAKE(0xFF, 0x45, 0x45)   /* red alert    */
#define CLR_GREEN    LV_COLOR_MAKE(0x4C, 0xAF, 0x50)
#define CLR_BAR_BG   LV_COLOR_MAKE(0x33, 0x33, 0x44)
#define CLR_SEPARATOR LV_COLOR_MAKE(0x2A, 0x2A, 0x3E)

/* ── Static widget references ────────────────────────────────────────── */

/* Zone 1 */
static lv_obj_t *z1_clock_label;
static lv_obj_t *z1_date_label;
static lv_obj_t *z1_env_label;
static lv_obj_t *z1_wifi_label;

/* Zone 2 */
static lv_obj_t *z2_pet_cont;
static lv_obj_t *z2_face_label;
static lv_anim_t z2_breathe_anim;
static pet_state_t z2_last_pet_state = (pet_state_t)-1; /* force initial update */

/* Zone 3 */
static lv_obj_t *z3_status_label;
static lv_obj_t *z3_dialog_label;
static lv_obj_t *z3_dialog_cont;

/* Zone 4 */
static lv_obj_t *z4_sit_bar;
static lv_obj_t *z4_sit_label;
static lv_obj_t *z4_drink_bar;
static lv_obj_t *z4_drink_label;
static lv_obj_t *z4_sit_alert_label;
static lv_obj_t *z4_drink_alert_label;

/* ── Helper: create zone container ───────────────────────────────────── */

static lv_obj_t *make_zone(lv_obj_t *parent, lv_coord_t y, lv_coord_t h,
                           lv_color_t bg, bool add_sep)
{
    lv_obj_t *zone = lv_obj_create(parent);
    lv_obj_set_size(zone, 1080, h);
    lv_obj_set_pos(zone, 0, y);
    lv_obj_set_style_bg_color(zone, bg, 0);
    lv_obj_set_style_border_width(zone, 0, 0);
    lv_obj_set_style_radius(zone, 0, 0);
    lv_obj_clear_flag(zone, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_scrollbar_mode(zone, LV_SCROLLBAR_MODE_OFF);

    if (add_sep)
    {
        lv_obj_t *line = lv_obj_create(zone);
        lv_obj_set_size(line, 1080, 1);
        lv_obj_set_pos(line, 0, 0);
        lv_obj_set_style_bg_color(line, CLR_SEPARATOR, 0);
        lv_obj_set_style_border_width(line, 0, 0);
        lv_obj_set_style_radius(line, 0, 0);
        lv_obj_clear_flag(line, LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_set_scrollbar_mode(line, LV_SCROLLBAR_MODE_OFF);
    }

    return zone;
}

/* ── Pet breathe animation ───────────────────────────────────────────── */

static void breathe_opa_cb(void *obj, int32_t v)
{
    lv_obj_set_style_opa((lv_obj_t *)obj, (lv_opa_t)v, 0);
}

static void restart_breathe_anim(pet_state_t state)
{
    lv_anim_t *a = &z2_breathe_anim;

    lv_anim_init(a);
    lv_anim_set_var(a, z2_pet_cont);
    lv_anim_set_exec_cb(a, breathe_opa_cb);

    switch (state)
    {
    case PET_SLEEPING:
        /* Slow, shallow breathing */
        lv_anim_set_values(a, LV_OPA_50, LV_OPA_80);
        lv_anim_set_time(a, 1800);
        lv_anim_set_playback_time(a, 1800);
        break;
    case PET_HAPPY:
        /* Fast, excited */
        lv_anim_set_values(a, LV_OPA_70, LV_OPA_COVER);
        lv_anim_set_time(a, 600);
        lv_anim_set_playback_time(a, 600);
        break;
    case PET_AWAKE:
    default:
        /* Normal */
        lv_anim_set_values(a, LV_OPA_70, LV_OPA_COVER);
        lv_anim_set_time(a, 1200);
        lv_anim_set_playback_time(a, 1200);
        break;
    }

    lv_anim_set_repeat_count(a, LV_ANIM_REPEAT_INFINITE);
    lv_anim_start(a);
}

/* ── Create Zone 1: Status & Environment ─────────────────────────────── */

static void create_zone1(lv_obj_t *scr)
{
    lv_obj_t *z1 = make_zone(scr, Z1_Y, Z1_H, CLR_Z1_BG, false);

    z1_clock_label = lv_label_create(z1);
    lv_label_set_text(z1_clock_label, "--:--");
    lv_obj_set_style_text_color(z1_clock_label, CLR_TEXT, 0);
    lv_obj_set_style_text_font(z1_clock_label, &lv_font_montserrat_48, 0);
    lv_obj_align(z1_clock_label, LV_ALIGN_TOP_LEFT, 24, 16);

    z1_date_label = lv_label_create(z1);
    lv_label_set_text(z1_date_label, "----/--/--");
    lv_obj_set_style_text_color(z1_date_label, CLR_TEXT_DIM, 0);
    lv_obj_set_style_text_font(z1_date_label, &lv_font_montserrat_16, 0);
    lv_obj_align_to(z1_date_label, z1_clock_label, LV_ALIGN_OUT_BOTTOM_LEFT, 0, 4);

    z1_wifi_label = lv_label_create(z1);
    lv_label_set_text(z1_wifi_label, "WiFi ✕");
    lv_obj_set_style_text_color(z1_wifi_label, CLR_TEXT_DIM, 0);
    lv_obj_set_style_text_font(z1_wifi_label, &lv_font_montserrat_16, 0);
    lv_obj_align(z1_wifi_label, LV_ALIGN_TOP_RIGHT, -24, 24);

    /* Environment row */
    z1_env_label = lv_label_create(z1);
    lv_label_set_text(z1_env_label, "--°C  |  --%  |  --- lux");
    lv_obj_set_style_text_color(z1_env_label, CLR_TEXT_DIM, 0);
    lv_obj_set_style_text_font(z1_env_label, &lv_font_montserrat_16, 0);
    lv_obj_align(z1_env_label, LV_ALIGN_BOTTOM_LEFT, 24, -16);
}

/* ── Create Zone 2: Pet ──────────────────────────────────────────────── */

static void create_zone2(lv_obj_t *scr)
{
    lv_obj_t *z2 = make_zone(scr, Z2_Y, Z2_H, CLR_Z2_BG, true);

    z2_pet_cont = lv_obj_create(z2);
    lv_obj_set_size(z2_pet_cont, 400, 400);
    lv_obj_center(z2_pet_cont);
    lv_obj_set_style_bg_color(z2_pet_cont, CLR_Z2_BG, 0);
    lv_obj_set_style_border_width(z2_pet_cont, 2, 0);
    lv_obj_set_style_border_color(z2_pet_cont, CLR_ACCENT, 0);
    lv_obj_set_style_radius(z2_pet_cont, 200, 0);   /* circle */
    lv_obj_clear_flag(z2_pet_cont, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_scrollbar_mode(z2_pet_cont, LV_SCROLLBAR_MODE_OFF);

    z2_face_label = lv_label_create(z2_pet_cont);
    lv_label_set_text(z2_face_label, "◕ ω ◕");
    lv_obj_set_style_text_color(z2_face_label, CLR_TEXT, 0);
    lv_obj_set_style_text_font(z2_face_label, &lv_font_montserrat_48, 0);
    lv_obj_center(z2_face_label);

    /* Start breathe animation */
    restart_breathe_anim(PET_AWAKE);
}

/* ── Create Zone 3: AI / Chat ────────────────────────────────────────── */

static void create_zone3(lv_obj_t *scr)
{
    lv_obj_t *z3 = make_zone(scr, Z3_Y, Z3_H, CLR_Z3_BG, true);

    z3_status_label = lv_label_create(z3);
