void ui_main_create(void)
{
    lv_obj_t *scr = lv_scr_act();
    lv_obj_set_style_bg_color(scr, CLR_BG, 0);
    lv_obj_set_scrollbar_mode(scr, LV_SCROLLBAR_MODE_OFF);

    create_zone1(scr);
    create_zone2(scr);
    create_zone3(scr);
    create_zone4(scr);

    /* Force initial update */
    const app_state_t *s = app_core_get_state();
    ui_main_update_zone1(s);
    ui_main_update_zone2(s);
    ui_main_update_zone3(s);
    ui_main_update_zone4(s);
}

/* ── Zone 1 ──────────────────────────────────────────────────────────── */

void ui_main_update_zone1(const app_state_t *state)
{
    char buf[64];

    /* Clock */
    snprintf(buf, sizeof(buf), "%02d:%02d", state->status.hour, state->status.minute);
    lv_label_set_text(z1_clock_label, buf);

    /* Date */
    snprintf(buf, sizeof(buf), "%04d/%02d/%02d",
             state->status.year, state->status.month, state->status.day);
    lv_label_set_text(z1_date_label, buf);

    /* Env */
    snprintf(buf, sizeof(buf), "%.1f°C  |  %.0f%%  |  %lu lux",
             state->status.temperature, state->status.humidity,
             (unsigned long)state->status.lux);
    lv_label_set_text(z1_env_label, buf);

    /* WiFi */
    lv_label_set_text(z1_wifi_label,
                      state->status.wifi_connected ? "WiFi ✓" : "WiFi ✕");
    lv_obj_set_style_text_color(z1_wifi_label,
                                state->status.wifi_connected ? CLR_GREEN : CLR_TEXT_DIM, 0);
}

/* ── Zone 2 ──────────────────────────────────────────────────────────── */

void ui_main_update_zone2(const app_state_t *state)
{
    if (state->pet.state == z2_last_pet_state) return;
    z2_last_pet_state = state->pet.state;

    switch (state->pet.state)
    {
    case PET_AWAKE:
        lv_label_set_text(z2_face_label, "◕ ω ◕");
        break;
    case PET_SLEEPING:
        lv_label_set_text(z2_face_label, "−(－_－)− zzz");
        break;
    case PET_HAPPY:
        lv_label_set_text(z2_face_label, "✧ ω ✧");
        break;
    }

    /* Restart breathe animation to match new state */
    restart_breathe_anim(state->pet.state);
}

/* ── Zone 3 ──────────────────────────────────────────────────────────── */

void ui_main_update_zone3(const app_state_t *state)
{
    lv_label_set_text(z3_status_label, state->ai.status_text);
    lv_label_set_text(z3_dialog_label, state->ai.dialog_buf);

    /* Auto-scroll to bottom to show latest line */
    lv_obj_scroll_to_y(z3_dialog_cont, lv_obj_get_scroll_bottom(z3_dialog_cont),
                       LV_ANIM_OFF);
}

/* ── Zone 4 ──────────────────────────────────────────────────────────── */

void ui_main_update_zone4(const app_state_t *state)
{
    char buf[48];
    uint32_t pct;

    /* Sit bar */
    pct = (state->health.sit_seconds * 100) / 2700;
    lv_bar_set_value(z4_sit_bar, state->health.sit_seconds, LV_ANIM_ON);
    snprintf(buf, sizeof(buf), "%lu%%", (unsigned long)pct);
    lv_label_set_text(z4_sit_label, buf);

    if (state->health.sit_alert)
    {
        lv_obj_set_style_bg_color(z4_sit_bar, CLR_ALERT, LV_PART_INDICATOR);
        lv_label_set_text(z4_sit_alert_label, "⚠ Move!");
    }
    else
    {
        lv_obj_set_style_bg_color(z4_sit_bar, CLR_GREEN, LV_PART_INDICATOR);
        lv_label_set_text(z4_sit_alert_label, "");
    }

    /* Drink bar */
    pct = (state->health.drink_seconds * 100) / 3600;
    lv_bar_set_value(z4_drink_bar, state->health.drink_seconds, LV_ANIM_ON);
    snprintf(buf, sizeof(buf), "%lu%%", (unsigned long)pct);
    lv_label_set_text(z4_drink_label, buf);

    if (state->health.drink_alert)
    {
        lv_obj_set_style_bg_color(z4_drink_bar, CLR_ALERT, LV_PART_INDICATOR);
        lv_label_set_text(z4_drink_alert_label, "⚠ Drink!");
    }
    else
    {
        lv_obj_set_style_bg_color(z4_drink_bar, LV_COLOR_MAKE(0x21, 0x96, 0xF3),
                                   LV_PART_INDICATOR);
        lv_label_set_text(z4_drink_alert_label, "");
    }
}

/****************************************************************************
 * apps/examples/desktop_companion/main.c
 *
 * Entry point — ties LVGL init, app core, and libuv loop together.
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <lvgl/lvgl.h>
#include <uv.h>

#include "app_core.h"
#include "ui_main.h"

int main(int argc, FAR char *argv[])
{
    lv_nuttx_dsc_t  info;
    lv_nuttx_result_t result;
    uv_loop_t       loop;

    /* ── LVGL initialisation ──────────────────────────────────────── */
    lv_init();

    lv_nuttx_dsc_init(&info);
    info.fb_path    = "/dev/fb0";
#ifdef CONFIG_INPUT_TOUCHSCREEN
    info.input_path = "/dev/input0";
#endif

    lv_nuttx_init(&info, &result);
    if (result.disp == NULL)
    {
        fprintf(stderr, "[DC] lv_nuttx_init failed\n");
        return 1;
    }

    /* Scale DPI for our large portrait display */
    lv_display_set_dpi(result.disp, 260);

    /* ── Application layers ────────────────────────────────────────── */
    app_core_init();          /* create state-machine timer    */
    ui_main_create();         /* build the 4‑zone UI          */

    /* ── Enter libuv event loop (drives LVGL + our timer) ──────── */
    lv_nuttx_uv_t uv_info;
    lv_memset(&uv_info, 0, sizeof(uv_info));
    uv_loop_init(&loop);
    uv_info.loop  = &loop;
    uv_info.disp  = result.disp;
    uv_info.indev = result.indev;

    void *uv_data = lv_nuttx_uv_init(&uv_info);
    if (uv_data == NULL)
    {
        fprintf(stderr, "[DC] lv_nuttx_uv_init failed\n");
        return 1;
    }

    printf("[DC] Desktop Companion started\n");
    uv_run(&loop, UV_RUN_DEFAULT);

    /* ── Cleanup (never reached in normal operation) ─────────────── */
    lv_nuttx_uv_deinit(&uv_data);
    lv_nuttx_deinit(&result);
    lv_deinit();
    return 0;
}

