26	    info.input_path = "/dev/input0";
27	#endif
28	
29	    lv_nuttx_init(&info, &result);
30	    if (result.disp == NULL)
31	    {
32	        fprintf(stderr, "[DC] lv_nuttx_init failed\n");
33	        return 1;
34	    }
35	
36	    /* Scale DPI for our large portrait display */
37	    lv_display_set_dpi(result.disp, 260);
38	
39	    /* ── Application layers ────────────────────────────────────────── */
40	    app_core_init();          /* create state-machine timer    */
41	    ui_main_create();         /* build the 4‑zone UI          */
42	
43	    printf("[DC] Desktop Companion started\n");
44	
45	    /* ── Simple poll loop (same pattern as working screentest) ──── */
46	    while (1)
47	    {
48	        uint32_t idle = lv_timer_handler();
49	        idle = idle ? idle : 1;
50	        usleep(idle * 1000);
51	    }
52	
53	    /* ── Cleanup (never reached) ──────────────────────────────────── */
54	    lv_nuttx_deinit(&result);
55	    lv_deinit();
56	    return 0;
57	}
