1	/****************************************************************************
2	 * apps/examples/desktop_companion/app_core.c
3	 *
4	 * Core Application State Machine
5	 ****************************************************************************/
6	
7	#include <nuttx/config.h>
8	#include <string.h>
9	#include <stdio.h>
10	#include <lvgl/lvgl.h>
11	
12	#include "app_core.h"
13	#include "ui_main.h"
14	#include "hal_api.h"
15	
16	/* ── Tunables ────────────────────────────────────────────────────────── */
17	
18	#define TICK_MS             1000    /* 1 second per tick */
19	#define SIT_THRESHOLD_S     2700    /* 45 min = 2700 s */
20	#define DRINK_THRESHOLD_S   3600    /* 60 min = 3600 s */
21	#define SLEEP_HYSTERESIS_S  5       /* person away this many ticks → SLEEP */
22	#define HAPPY_DURATION_S    3       /* keep HAPPY face this many ticks */
23	
24	/* ── Private state ───────────────────────────────────────────────────── */
25	
26	static app_state_t  g_state;
27	static bool         g_dirty;                 /* any field changed this tick */
28	static bool         g_pet_dirty;             /* pet state / proximity changed */
29	static bool         g_zone1_dirty;           /* status bar changed */
30	static bool         g_zone3_dirty;           /* AI text / state changed */
31	static bool         g_zone4_dirty;           /* health changed */
32	
33	/* ── Forward declarations ────────────────────────────────────────────── */
34	
35	static void app_timer_cb(lv_timer_t *timer);
36	
37	/* ── Initialisation ──────────────────────────────────────────────────── */
38	
39	void app_core_init(void)
40	{
41	    memset(&g_state, 0, sizeof(g_state));
42	    g_state.pet.state          = PET_AWAKE;
43	    g_state.ai.state           = AI_IDLE;
44	    strcpy(g_state.ai.status_text, "[mic idle]");
45	
46	    g_dirty = g_pet_dirty = g_zone1_dirty = g_zone3_dirty = g_zone4_dirty = true;
47	
48	    /* Create 1‑second LVGL timer — auto‑integrated with libuv. */
49	    lv_timer_create(app_timer_cb, TICK_MS, NULL);
50	}
51	
52	/* ── State accessors ─────────────────────────────────────────────────── */
53	
54	const app_state_t *app_core_get_state(void)
55	{
56	    return &g_state;
57	}
58	
59	void app_core_set_ai_text(const char *text)
60	{
61	    /* Append to ring buffer */
62	    size_t cur = strlen(g_state.ai.dialog_buf);
63	    size_t tlen = strlen(text);
64	    if (cur + tlen + 3 > sizeof(g_state.ai.dialog_buf))
65	    {
66	        /* Evict oldest half */
67	        char *p = g_state.ai.dialog_buf;
68	        char *mid = p + sizeof(g_state.ai.dialog_buf) / 2;
69	        while (*mid) *p++ = *mid++;
70	        *p = '\0';
71	        cur = strlen(g_state.ai.dialog_buf);
72	    }
73	    if (cur > 0) { strcat(g_state.ai.dialog_buf, "\n"); cur++; }
74	    strcat(g_state.ai.dialog_buf, text);
75	
76	    g_zone3_dirty = true;
77	}
78	
79	void app_core_set_ai_state(ai_state_t s)
80	{
81	    if (g_state.ai.state == s) return;
82	    g_state.ai.state = s;
83	    switch (s)
84	    {
85	        case AI_IDLE:      snprintf(g_state.ai.status_text, sizeof(g_state.ai.status_text), "[mic idle]");       break;
86	        case AI_LISTENING: snprintf(g_state.ai.status_text, sizeof(g_state.ai.status_text), "[listening...]");   break;
87	        case AI_THINKING:  snprintf(g_state.ai.status_text, sizeof(g_state.ai.status_text), "[thinking...]");    break;
88	        case AI_SPEAKING:  snprintf(g_state.ai.status_text, sizeof(g_state.ai.status_text), "[speaking...]");    break;
89	    }
90	    g_zone3_dirty = true;
91	}
92	
93	void app_core_drink_reset(void)
94	{
95	    g_state.health.drink_seconds  = 0;
96	    g_state.health.drink_alert    = false;
97	    g_zone4_dirty = true;
98	}
99	
100	void app_core_sit_reset(void)
101	{
102	    g_state.health.sit_seconds    = 0;
103	    g_state.health.sit_alert      = false;
104	    g_zone4_dirty = true;
105	}
106	
107	/* ── Pet FSM update ──────────────────────────────────────────────────── */
108	
109	static void update_pet(bool person_present)
110	{
111	    switch (g_state.pet.state)
112	    {
113	    case PET_AWAKE:
114	        if (!person_present)
115	        {
116	            /* Start counting away‑time */
117	            g_state.pet.happy_timer++;
118	            if (g_state.pet.happy_timer >= SLEEP_HYSTERESIS_S)
119	            {
120	                g_state.pet.state = PET_SLEEPING;
121	                g_state.pet.happy_timer = 0;
122	                g_pet_dirty = true;
123	            }
124	        }
125	        else
126	        {
127	            g_state.pet.happy_timer = 0; /* reset away‑counter */
128	        }
129	        break;
130	
131	    case PET_SLEEPING:
132	        if (person_present)
133	        {
134	            /* Person just arrived → HAPPY for a few seconds */
135	            g_state.pet.state       = PET_HAPPY;
136	            g_state.pet.happy_timer = HAPPY_DURATION_S;
137	            g_pet_dirty = true;
138	        }
139	        break;
140	
141	    case PET_HAPPY:
142	        if (g_state.pet.happy_timer > 0)
143	        {
144	            g_state.pet.happy_timer--;
145	        }
146	        if (g_state.pet.happy_timer == 0)
147	        {
148	            g_state.pet.state = person_present ? PET_AWAKE : PET_SLEEPING;
149	            g_pet_dirty = true;
150	        }
151	        /* If person left while happy, transition normally */
152	        break;
153	    }
154	}
155	
156	/* ── Health timers ───────────────────────────────────────────────────── */
157	
158	static void update_health(void)
159	{
160	    bool dirty_local = false;
161	
162	    if (g_state.health.sit_seconds < SIT_THRESHOLD_S)
163	    {
164	        g_state.health.sit_seconds++;
165	        if (g_state.health.sit_seconds >= SIT_THRESHOLD_S)
166	        {
167	            g_state.health.sit_alert = true;
168	        }
169	        dirty_local = true;
170	    }
171	
172	    if (g_state.health.drink_seconds < DRINK_THRESHOLD_S)
173	    {
174	        g_state.health.drink_seconds++;
175	        if (g_state.health.drink_seconds >= DRINK_THRESHOLD_S)
176	        {
177	            g_state.health.drink_alert = true;
178	        }
179	        dirty_local = true;
180	    }
181	
182	    if (dirty_local) g_zone4_dirty = true;
183	}
184	
185	/* ── Zone‑1 clock & env update ───────────────────────────────────────── */
186	
187	static void update_clock_and_env(void)
188	{
189	    /* TODO: replace with proper RTC time‑of‑day call */
190	    /* For now: increment simulated time every tick (1 s) */
191	    g_state.status.second++;
192	    if (g_state.status.second >= 60)
193	    {
194	        g_state.status.second = 0;
195	        g_state.status.minute++;
196	        if (g_state.status.minute >= 60)
197	        {
198	            g_state.status.minute = 0;
199	            g_state.status.hour   = (g_state.status.hour + 1) % 24;
200	        }
201	    }
202	
203	    /* Poll HAL sensors (non‑blocking stubs for now) */
204	    {
205	        uint16_t dist;
206	        bool     present;
207	        float    t, h;
208	        uint32_t lx;
209	
210	        hal_sensor_get_proximity(&dist, &present);
211	        hal_sensor_get_env(&t, &h, &lx);
212	
213	        if (g_state.pet.proximity_raw != dist)
214	        {
215	            g_state.pet.proximity_raw = dist;
216	            g_pet_dirty = true;
217	        }
218	        /* Person‑present: hysteresis inside pet FSM */
219	        g_state.pet.person_present = present;
220	
221	        if (g_state.status.temperature != t ||
222	            g_state.status.humidity    != h ||
223	            g_state.status.lux         != lx)
224	        {
225	            g_state.status.temperature = t;
226	            g_state.status.humidity    = h;
227	            g_state.status.lux         = lx;
228	            g_zone1_dirty = true;
229	        }
230	    }
231	
232	    g_zone1_dirty = true; /* clock always advances */
233	}
234	
235	/* ── LVGL timer callback ─────────────────────────────────────────────── */
236	
237	static void app_timer_cb(lv_timer_t *timer)
238	{
239	    (void)timer;
240	
241	    g_state.tick_count++;
242	
243	    /* 1. Clock + Environment (Zone 1) */
244	    update_clock_and_env();
245	
246	    /* 2. Pet FSM (Zone 2) */
247	    update_pet(g_state.pet.person_present);
248	
249	    /* 3. Health timers (Zone 4) */
250	    update_health();
251	
252	    /* 4. Flush all dirty flags to UI layer */
253	    if (g_zone1_dirty || g_dirty)  ui_main_update_zone1(&g_state);
254	    if (g_pet_dirty  || g_dirty)   ui_main_update_zone2(&g_state);
255	    if (g_zone3_dirty || g_dirty)  ui_main_update_zone3(&g_state);
256	    if (g_zone4_dirty || g_dirty)  ui_main_update_zone4(&g_state);
257	
258	    g_dirty = g_zone1_dirty = g_pet_dirty = g_zone3_dirty = g_zone4_dirty = false;
259	}
