277	{
278	    if (st->pet.state == last_pet) return;
279	    last_pet = st->pet.state;
280	
281	    switch (st->pet.state) {
282	    case PET_AWAKE:    lv_label_set_text(w_face, "O  w  O"); break;
283	    case PET_SLEEPING: lv_label_set_text(w_face, "-  -  z"); break;
284	    case PET_HAPPY:    lv_label_set_text(w_face, "^  w  ^"); break;
