314	        lv_obj_set_style_bg_color(w_sit_bar, CLR_GREEN, LV_PART_INDICATOR);
315	        lv_label_set_text(w_sit_alert, "");
316	    }
317	
318	    pct = (st->health.drink_seconds * 100) / 3600;
319	    lv_bar_set_value(w_drink_bar, st->health.drink_seconds, LV_ANIM_ON);
320	    snprintf(b, sizeof(b), "%lu%%", (unsigned long)pct);
321	    lv_label_set_text(w_drink_pct, b);
322	
323	    if (st->health.drink_alert) {
324	        lv_obj_set_style_bg_color(w_drink_bar, CLR_ALERT, LV_PART_INDICATOR);
325	        lv_label_set_text(w_drink_alert, "DRINK!");
326	    } else {
327	        lv_obj_set_style_bg_color(w_drink_bar, CLR_BLUE, LV_PART_INDICATOR);
328	        lv_label_set_text(w_drink_alert, "");
329	    }
