/****************************************************************************
 * apps/examples/desktop_companion/ui_main.c
 *
 * UI View Layer — LVGL9 纯绝对定位版。
 * 所有 container 创建后立即关闭 layout/scroll/padding，避免 LVGL9 默认
 * flex layout 覆盖手动 set_pos。
 ****************************************************************************/

#include <nuttx/config.h>
#include <string.h>
#include <stdio.h>
#include <lvgl/lvgl.h>

#include "ui_main.h"
#include "app_core.h"

/* ── Colour palette ──────────────────────────────────────────────────── */

#define CLR_BG       lv_color_hex(0x0F0F23)
#define CLR_TEXT     lv_color_hex(0xE0E0E0)
#define CLR_TEXT_DIM lv_color_hex(0x808090)
#define CLR_ACCENT   lv_color_hex(0x00BFFF)
#define CLR_ALERT    lv_color_hex(0xFF4545)
#define CLR_GREEN    lv_color_hex(0x4CAF50)
#define CLR_BLUE     lv_color_hex(0x2196F3)
#define CLR_BAR_BG   lv_color_hex(0x333344)
#define CLR_SEP      lv_color_hex(0x2A2A3E)

/* ── 统一 container 初始化：关闭 LVGL9 默认 layout/scroll/padding ───── */

static void lv_obj_prepare(lv_obj_t *obj)
{
    lv_obj_set_layout(obj, LV_LAYOUT_NONE);
    lv_obj_clear_flag(obj, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_all(obj, 0, 0);
    lv_obj_set_style_border_width(obj, 0, 0);
    lv_obj_set_style_radius(obj, 0, 0);
}

/* ── Static widget pointers ──────────────────────────────────────────── */

/* Zone 1 — Status */
static lv_obj_t *w_clock;
static lv_obj_t *w_date;
static lv_obj_t *w_wifi;
static lv_obj_t *w_env;

/* Zone 2 — Pet */
static lv_obj_t *w_pet_bg;
static lv_obj_t *w_face;
static lv_anim_t w_breathe;
static pet_state_t last_pet = (pet_state_t)-1;

/* Zone 3 — AI */
static lv_obj_t *w_ai_status;
static lv_obj_t *w_ai_dialog;
static lv_obj_t *w_ai_cont;

/* Zone 4 — Health */
static lv_obj_t *w_sit_bar;
static lv_obj_t *w_sit_pct;
static lv_obj_t *w_sit_alert;
static lv_obj_t *w_drink_bar;
static lv_obj_t *w_drink_pct;
static lv_obj_t *w_drink_alert;

/* ── Separator line ──────────────────────────────────────────────────── */

static void add_sep(lv_obj_t *parent, lv_coord_t y)
{
    lv_obj_t *l = lv_line_create(parent);
    /* lv_line 没有 layout 问题，只需设置坐标和样式 */
    lv_obj_set_pos(l, 0, y);
    lv_obj_set_size(l, 1080, 1);
    lv_obj_set_style_bg_color(l, CLR_SEP, 0);
    lv_obj_set_style_border_width(l, 0, 0);
    lv_obj_prepare(l);
}

/* ── Breathe animation ──────────────────────────────────────────────── */

static void breathe_cb(void *obj, int32_t v)
{
    lv_obj_set_style_opa((lv_obj_t *)obj, (lv_opa_t)v, 0);
}

static void restart_breathe(pet_state_t st)
{
    lv_anim_t *a = &w_breathe;
    lv_anim_init(a);
    lv_anim_set_var(a, w_pet_bg);
    lv_anim_set_exec_cb(a, breathe_cb);
    switch (st) {
    case PET_SLEEPING:
        lv_anim_set_values(a, 50, 80);
        lv_anim_set_time(a, 1800);
        lv_anim_set_playback_time(a, 1800);
        break;
    case PET_HAPPY:
        lv_anim_set_values(a, 70, 100);
        lv_anim_set_time(a, 600);
        lv_anim_set_playback_time(a, 600);
        break;
    default:
        lv_anim_set_values(a, 70, 100);
        lv_anim_set_time(a, 1200);
        lv_anim_set_playback_time(a, 1200);
        break;
    }
    lv_anim_set_repeat_count(a, LV_ANIM_REPEAT_INFINITE);
    lv_anim_start(a);
}

/* ══════════════════════════════════════════════════════════════════════ */
/*  Public API                                                          */
/* ══════════════════════════════════════════════════════════════════════ */

void ui_main_create(void)
{
    lv_obj_t *scr = lv_scr_act();
    lv_obj_set_style_bg_color(scr, CLR_BG, 0);
    lv_obj_prepare(scr);

    /* ══════ Zone 1: Status (y 0–390) ══════ */

    w_clock = lv_label_create(scr);
    lv_label_set_text(w_clock, "--:--");
    lv_obj_set_style_text_color(w_clock, CLR_TEXT, 0);
    lv_obj_set_style_text_font(w_clock, &lv_font_montserrat_48, 0);
    lv_obj_set_pos(w_clock, 24, 16);

    w_date = lv_label_create(scr);
    lv_label_set_text(w_date, "----/--/--");
    lv_obj_set_style_text_color(w_date, CLR_TEXT_DIM, 0);
    lv_obj_set_style_text_font(w_date, &lv_font_montserrat_16, 0);
    lv_obj_set_pos(w_date, 24, 80);

    w_wifi = lv_label_create(scr);
    lv_label_set_text(w_wifi, "WiFi");
    lv_obj_set_style_text_color(w_wifi, CLR_TEXT_DIM, 0);
    lv_obj_set_style_text_font(w_wifi, &lv_font_montserrat_16, 0);
    lv_obj_set_pos(w_wifi, 1000, 24);

    w_env = lv_label_create(scr);
    lv_label_set_text(w_env, "--C  --%  --- lux");
    lv_obj_set_style_text_color(w_env, CLR_TEXT_DIM, 0);
    lv_obj_set_style_text_font(w_env, &lv_font_montserrat_16, 0);
    lv_obj_set_pos(w_env, 24, 340);

    add_sep(scr, 390);

    /* ══════ Zone 2: Pet (y 410–1290) ══════ */

    w_pet_bg = lv_obj_create(scr);
    lv_obj_prepare(w_pet_bg);
    lv_obj_set_size(w_pet_bg, 300, 300);
    lv_obj_set_pos(w_pet_bg, 390, 550);
    lv_obj_set_style_bg_color(w_pet_bg, lv_color_hex(0x1A1A2E), 0);
    lv_obj_set_style_border_width(w_pet_bg, 2, 0);
    lv_obj_set_style_border_color(w_pet_bg, CLR_ACCENT, 0);
    lv_obj_set_style_radius(w_pet_bg, 150, 0);

    w_face = lv_label_create(w_pet_bg);
    lv_label_set_text(w_face, "O_O");
    lv_obj_set_style_text_color(w_face, CLR_TEXT, 0);
    lv_obj_set_style_text_font(w_face, &lv_font_montserrat_48, 0);
    lv_obj_center(w_face);

    restart_breathe(PET_AWAKE);

    add_sep(scr, 1290);

    /* ══════ Zone 3: AI (y 1310–1790) ══════ */

    w_ai_status = lv_label_create(scr);
    lv_label_set_text(w_ai_status, "[mic idle]");
    lv_obj_set_style_text_color(w_ai_status, CLR_ACCENT, 0);
    lv_obj_set_style_text_font(w_ai_status, &lv_font_montserrat_16, 0);
    lv_obj_set_pos(w_ai_status, 24, 1310);

    w_ai_cont = lv_obj_create(scr);
    lv_obj_prepare(w_ai_cont);
    lv_obj_set_size(w_ai_cont, 1032, 380);
    lv_obj_set_pos(w_ai_cont, 24, 1350);
    lv_obj_set_style_bg_color(w_ai_cont, lv_color_hex(0x0A0A18), 0);
    lv_obj_set_style_border_width(w_ai_cont, 1, 0);
    lv_obj_set_style_border_color(w_ai_cont, CLR_SEP, 0);
    lv_obj_set_style_radius(w_ai_cont, 8, 0);

    w_ai_dialog = lv_label_create(w_ai_cont);
    lv_label_set_text(w_ai_dialog, "");
    lv_obj_set_style_text_color(w_ai_dialog, CLR_TEXT_DIM, 0);
    lv_obj_set_style_text_font(w_ai_dialog, &lv_font_montserrat_16, 0);
    lv_obj_set_pos(w_ai_dialog, 8, 8);

    add_sep(scr, 1790);

    /* ══════ Zone 4: Health (y 1810–2160) ══════ */

    lv_obj_t *tl;
    tl = lv_label_create(scr);
    lv_label_set_text(tl, "Sit");
    lv_obj_set_style_text_color(tl, CLR_TEXT, 0);
    lv_obj_set_style_text_font(tl, &lv_font_montserrat_16, 0);
    lv_obj_set_pos(tl, 24, 1820);

    w_sit_bar = lv_bar_create(scr);
    lv_obj_set_size(w_sit_bar, 800, 20);
    lv_obj_set_pos(w_sit_bar, 80, 1820);
    lv_bar_set_range(w_sit_bar, 0, 2700);
    lv_bar_set_value(w_sit_bar, 0, LV_ANIM_OFF);
    lv_obj_set_style_bg_color(w_sit_bar, CLR_BAR_BG, 0);
    lv_obj_set_style_border_width(w_sit_bar, 0, 0);
    lv_obj_set_style_radius(w_sit_bar, 4, 0);
    lv_obj_set_style_bg_color(w_sit_bar, CLR_GREEN, LV_PART_INDICATOR);

    w_sit_pct = lv_label_create(scr);
    lv_label_set_text(w_sit_pct, "0%");
    lv_obj_set_style_text_color(w_sit_pct, CLR_TEXT_DIM, 0);
    lv_obj_set_style_text_font(w_sit_pct, &lv_font_montserrat_16, 0);
    lv_obj_set_pos(w_sit_pct, 890, 1820);

    w_sit_alert = lv_label_create(scr);
    lv_label_set_text(w_sit_alert, "");
    lv_obj_set_style_text_color(w_sit_alert, CLR_ALERT, 0);
    lv_obj_set_style_text_font(w_sit_alert, &lv_font_montserrat_16, 0);
    lv_obj_set_pos(w_sit_alert, 960, 1820);

    tl = lv_label_create(scr);
    lv_label_set_text(tl, "Drink");
    lv_obj_set_style_text_color(tl, CLR_TEXT, 0);
    lv_obj_set_style_text_font(tl, &lv_font_montserrat_16, 0);
    lv_obj_set_pos(tl, 24, 1880);

    w_drink_bar = lv_bar_create(scr);
    lv_obj_set_size(w_drink_bar, 800, 20);
    lv_obj_set_pos(w_drink_bar, 80, 1880);
    lv_bar_set_range(w_drink_bar, 0, 3600);
    lv_bar_set_value(w_drink_bar, 0, LV_ANIM_OFF);
    lv_obj_set_style_bg_color(w_drink_bar, CLR_BAR_BG, 0);
    lv_obj_set_style_border_width(w_drink_bar, 0, 0);
    lv_obj_set_style_radius(w_drink_bar, 4, 0);
    lv_obj_set_style_bg_color(w_drink_bar, CLR_BLUE, LV_PART_INDICATOR);

    w_drink_pct = lv_label_create(scr);
    lv_label_set_text(w_drink_pct, "0%");
    lv_obj_set_style_text_color(w_drink_pct, CLR_TEXT_DIM, 0);
    lv_obj_set_style_text_font(w_drink_pct, &lv_font_montserrat_16, 0);
    lv_obj_set_pos(w_drink_pct, 890, 1880);

    w_drink_alert = lv_label_create(scr);
    lv_label_set_text(w_drink_alert, "");
    lv_obj_set_style_text_color(w_drink_alert, CLR_ALERT, 0);
    lv_obj_set_style_text_font(w_drink_alert, &lv_font_montserrat_16, 0);
    lv_obj_set_pos(w_drink_alert, 960, 1880);

    /* Force initial update */
    const app_state_t *st = app_core_get_state();
    ui_main_update_zone1(st);
    ui_main_update_zone2(st);
    ui_main_update_zone3(st);
    ui_main_update_zone4(st);
}

/* ── Zone 1 ──────────────────────────────────────────────────────────── */

void ui_main_update_zone1(const app_state_t *st)
{
    char buf[64];
    snprintf(buf, sizeof(buf), "%02d:%02d", st->status.hour, st->status.minute);
    lv_label_set_text(w_clock, buf);

    snprintf(buf, sizeof(buf), "%04d/%02d/%02d",
             st->status.year, st->status.month, st->status.day);
    lv_label_set_text(w_date, buf);

    snprintf(buf, sizeof(buf), "%.1fC  %.0f%%  %lu lux",
             st->status.temperature, st->status.humidity,
             (unsigned long)st->status.lux);
    lv_label_set_text(w_env, buf);

    lv_label_set_text(w_wifi, st->status.wifi_connected ? "WiFi OK" : "WiFi --");
    lv_obj_set_style_text_color(w_wifi,
        st->status.wifi_connected ? CLR_GREEN : CLR_TEXT_DIM, 0);
}

/* ── Zone 2 ──────────────────────────────────────────────────────────── */

void ui_main_update_zone2(const app_state_t *st)
{
    if (st->pet.state == last_pet) return;
    last_pet = st->pet.state;

    switch (st->pet.state) {
    case PET_AWAKE:    lv_label_set_text(w_face, "O  w  O"); break;
    case PET_SLEEPING: lv_label_set_text(w_face, "-  -  z"); break;
    case PET_HAPPY:    lv_label_set_text(w_face, "^  w  ^"); break;
    }

    restart_breathe(st->pet.state);
}

/* ── Zone 3 ──────────────────────────────────────────────────────────── */

void ui_main_update_zone3(const app_state_t *st)
{
    lv_label_set_text(w_ai_status, st->ai.status_text);
    lv_label_set_text(w_ai_dialog, st->ai.dialog_buf);
}

/* ── Zone 4 ──────────────────────────────────────────────────────────── */

void ui_main_update_zone4(const app_state_t *st)
{
    char b[32];
    uint32_t pct;

    pct = (st->health.sit_seconds * 100) / 2700;
    lv_bar_set_value(w_sit_bar, st->health.sit_seconds, LV_ANIM_ON);
    snprintf(b, sizeof(b), "%lu%%", (unsigned long)pct);
    lv_label_set_text(w_sit_pct, b);

    if (st->health.sit_alert) {
        lv_obj_set_style_bg_color(w_sit_bar, CLR_ALERT, LV_PART_INDICATOR);
        lv_label_set_text(w_sit_alert, "MOVE!");
    } else {
        lv_obj_set_style_bg_color(w_sit_bar, CLR_GREEN, LV_PART_INDICATOR);
        lv_label_set_text(w_sit_alert, "");
    }

    pct = (st->health.drink_seconds * 100) / 3600;
    lv_bar_set_value(w_drink_bar, st->health.drink_seconds, LV_ANIM_ON);
    snprintf(b, sizeof(b), "%lu%%", (unsigned long)pct);
    lv_label_set_text(w_drink_pct, b);

    if (st->health.drink_alert) {
        lv_obj_set_style_bg_color(w_drink_bar, CLR_ALERT, LV_PART_INDICATOR);
        lv_label_set_text(w_drink_alert, "DRINK!");
    } else {
        lv_obj_set_style_bg_color(w_drink_bar, CLR_BLUE, LV_PART_INDICATOR);
        lv_label_set_text(w_drink_alert, "");
    }
}

