/****************************************************************************
 * apps/examples/desktop_companion/ui_main.c
 *
 * Minimal UI — colored blocks only, NO animation, NO containers.
 * Purpose: verify LVGL rendering pipeline is solid before adding features.
 ****************************************************************************/

#include <nuttx/config.h>
#include <string.h>
#include <stdio.h>
#include <lvgl/lvgl.h>

#include "ui_main.h"
#include "app_core.h"

/* ── Colour palette ──────────────────────────────────────────────────── */

#define C_RED    lv_color_hex(0xFF0000)
#define C_GREEN  lv_color_hex(0x00FF00)
#define C_BLUE   lv_color_hex(0x0000FF)
#define C_WHITE  lv_color_hex(0xFFFFFF)
#define C_DIM    lv_color_hex(0x808090)

/* ── Static widget pointers ──────────────────────────────────────────── */

static lv_obj_t *w_clock;
static lv_obj_t *w_env;
static lv_obj_t *w_red;
static lv_obj_t *w_green;
static lv_obj_t *w_blue;

/* ══════════════════════════════════════════════════════════════════════ */

void ui_main_create(void)
{
    lv_obj_t *scr = lv_scr_act();
    lv_obj_set_style_bg_color(scr, lv_color_hex(0x000000), 0);

    /* Zone 1 — clock label */
    w_clock = lv_label_create(scr);
    lv_label_set_text(w_clock, "--:--");
    lv_obj_set_style_text_color(w_clock, C_DIM, 0);
    lv_obj_set_pos(w_clock, 20, 20);

    /* Zone 2 — sensor values */
    w_env = lv_label_create(scr);
    lv_label_set_text(w_env, "sensor stub");
    lv_obj_set_style_text_color(w_env, C_DIM, 0);
    lv_obj_set_pos(w_env, 20, 60);

    /* Zone 3 — RED square at (200, 500) size 300x300 */
    w_red = lv_obj_create(scr);
    lv_obj_set_size(w_red, 300, 300);
    lv_obj_set_pos(w_red, 200, 500);
    lv_obj_set_style_bg_color(w_red, C_RED, 0);
    lv_obj_set_style_border_width(w_red, 0, 0);
    lv_obj_set_style_radius(w_red, 150, 0);

    /* Zone 4 — GREEN square at (600, 1200) size 300x300 */
    w_green = lv_obj_create(scr);
    lv_obj_set_size(w_green, 300, 300);
    lv_obj_set_pos(w_green, 600, 1200);
    lv_obj_set_style_bg_color(w_green, C_GREEN, 0);
    lv_obj_set_style_border_width(w_green, 0, 0);
    lv_obj_set_style_radius(w_green, 150, 0);

    /* Zone 5 — BLUE square at (200, 1800) size 300x300 */
    w_blue = lv_obj_create(scr);
    lv_obj_set_size(w_blue, 300, 300);
    lv_obj_set_pos(w_blue, 200, 1800);
    lv_obj_set_style_bg_color(w_blue, C_BLUE, 0);
    lv_obj_set_style_border_width(w_blue, 0, 0);
    lv_obj_set_style_radius(w_blue, 150, 0);

    /* Force initial update */
    const app_state_t *st = app_core_get_state();
    ui_main_update_zone1(st);
}

/* ── Updates ─────────────────────────────────────────────────────────── */

void ui_main_update_zone1(const app_state_t *st)
{
    char buf[64];
    snprintf(buf, sizeof(buf), "%02d:%02d", st->status.hour, st->status.minute);
    lv_label_set_text(w_clock, buf);

    snprintf(buf, sizeof(buf), "%.1fC  %.0f%%  %lu lux",
             st->status.temperature, st->status.humidity,
             (unsigned long)st->status.lux);
    lv_label_set_text(w_env, buf);
}

void ui_main_update_zone2(const app_state_t *st) { (void)st; }
void ui_main_update_zone3(const app_state_t *st) { (void)st; }
void ui_main_update_zone4(const app_state_t *st) { (void)st; }

